/**
 * Bulk-safe handler for ContactTrigger.
 *
 * Behaviour (unchanged from the legacy trigger):
 *  - before insert / before update: default a blank Contact.MailingCountry from
 *    Account.BillingCountry; on insert also default a blank Contact.LeadSource from
 *    Account.AccountSource.
 *  - after insert: if a new contact has a Phone and its Account has none, copy the
 *    contact phone to the account. When several new contacts of the same account have a
 *    phone, the first one in trigger order wins.
 *
 * Limits: at most 1 SOQL query per context (2 in total for an insert) and 1 DML statement.
 *
 * Declared "without sharing" on purpose: the legacy trigger ran in system context, so the
 * defaults must still be applied when the running user cannot see the parent account.
 */
public without sharing class ContactTriggerHandler {

    public void beforeInsert(List<Contact> newContacts) {
        applyAccountDefaults(newContacts, true);
    }

    public void beforeUpdate(List<Contact> newContacts, Map<Id, Contact> oldMap) {
        applyAccountDefaults(newContacts, false);
    }

    public void afterInsert(List<Contact> newContacts) {
        setAccountPhoneFromContacts(newContacts);
    }

    /**
     * Defaults MailingCountry (insert + update) and LeadSource (insert only) from the
     * parent Account. One SOQL query for the whole batch, no DML.
     */
    private void applyAccountDefaults(List<Contact> newContacts, Boolean isInsert) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newContacts) {
            if (c.AccountId != null
                && (String.isBlank(c.MailingCountry) || (isInsert && String.isBlank(c.LeadSource)))) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT Id, BillingCountry, AccountSource FROM Account WHERE Id IN :accountIds]
        );

        for (Contact c : newContacts) {
            if (c.AccountId == null) {
                continue;
            }
            Account a = accountsById.get(c.AccountId);
            if (a == null) {
                continue;
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }
            if (isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }

    /**
     * Copies the phone of the first (in trigger order) new contact with a phone onto its
     * Account when the account has no phone yet. One SOQL query and one DML statement for
     * the whole batch.
     */
    private void setAccountPhoneFromContacts(List<Contact> newContacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newContacts) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT Id, Phone FROM Account WHERE Id IN :accountIds]
        );

        // Preserves "first contact in trigger order wins" semantics.
        Map<Id, Account> accountsToUpdate = new Map<Id, Account>();
        for (Contact c : newContacts) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }
            if (accountsToUpdate.containsKey(c.AccountId)) {
                continue; // an earlier contact already claimed this account
            }
            Account a = accountsById.get(c.AccountId);
            if (a != null && String.isBlank(a.Phone)) {
                accountsToUpdate.put(c.AccountId, new Account(Id = a.Id, Phone = c.Phone));
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate.values();
        }
    }
}
