/**
 * Client for the FX rate provider configured as the Named Credential FB_Exchange_Rates.
 */
public with sharing class ExchangeRateClient {

    public class ExchangeRateException extends Exception {}

    @TestVisible private static final String ENDPOINT = 'callout:FB_Exchange_Rates/v1/latest';
    private static final Integer TIMEOUT_MS = 30000;
    private static final Integer MAX_ATTEMPTS = 2; // one request plus one retry on 503

    /**
     * Returns a map of normalised quote currency code -> rate relative to the base currency.
     */
    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        // ---- Validation (no callout is made if anything is wrong) ----
        String base = normaliseCode(baseCurrency);
        if (base == null) {
            throw new ExchangeRateException('Invalid base currency code: ' + baseCurrency);
        }
        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('At least one quote currency code is required.');
        }
        Set<String> quotes = new Set<String>();
        for (String raw : quoteCurrencies) {
            String code = normaliseCode(raw);
            if (code == null) {
                throw new ExchangeRateException('Invalid quote currency code: ' + raw);
            }
            quotes.add(code);
        }

        // ---- Build and send the request (retry once on 503) ----
        String symbols = String.join(new List<String>(quotes), ',');
        String url = ENDPOINT + '?base=' + base + '&symbols=' + symbols;

        HttpResponse response;
        Http http = new Http();
        for (Integer attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
            response = http.send(buildRequest(url));
            if (response.getStatusCode() != 503) {
                break;
            }
        }

        Integer status = response.getStatusCode();
        if (status != 200) {
            throw new ExchangeRateException(
                'Exchange rate service returned HTTP status ' + status + ' (' + response.getStatus() + ').'
            );
        }

        // ---- Parse the response ----
        Map<String, Object> rates;
        try {
            Object parsed = JSON.deserializeUntyped(response.getBody());
            if (!(parsed instanceof Map<String, Object>)) {
                throw new ExchangeRateException('Unexpected response body.');
            }
            Object ratesObj = ((Map<String, Object>) parsed).get('rates');
            if (!(ratesObj instanceof Map<String, Object>)) {
                throw new ExchangeRateException('Response does not contain a "rates" object.');
            }
            rates = (Map<String, Object>) ratesObj;
        } catch (ExchangeRateException e) {
            throw e;
        } catch (Exception e) {
            throw new ExchangeRateException('Unable to parse exchange rate response: ' + e.getMessage(), e);
        }

        Map<String, Decimal> result = new Map<String, Decimal>();
        for (String code : quotes) {
            Decimal rate = toDecimal(rates.get(code));
            if (rate == null) {
                throw new ExchangeRateException('No rate returned for currency ' + code + '.');
            }
            result.put(code, rate);
        }
        return result;
    }

    private static HttpRequest buildRequest(String url) {
        HttpRequest request = new HttpRequest();
        request.setEndpoint(url);
        request.setMethod('GET');
        request.setHeader('Accept', 'application/json');
        request.setTimeout(TIMEOUT_MS);
        return request;
    }

    /** Trims and upper-cases a code; returns null when the result is not exactly three letters A-Z. */
    private static String normaliseCode(String raw) {
        if (raw == null) {
            return null;
        }
        String code = raw.trim().toUpperCase();
        return Pattern.matches('[A-Z]{3}', code) ? code : null;
    }

    private static Decimal toDecimal(Object value) {
        if (value == null) {
            return null;
        }
        if (value instanceof Decimal) {
            return (Decimal) value;
        }
        if (value instanceof Integer) {
            return Decimal.valueOf((Integer) value);
        }
        if (value instanceof Long) {
            return Decimal.valueOf((Long) value);
        }
        if (value instanceof Double) {
            return Decimal.valueOf((Double) value);
        }
        if (value instanceof String) {
            try {
                return Decimal.valueOf(((String) value).trim());
            } catch (Exception e) {
                return null;
            }
        }
        return null;
    }
}
