/**
 * Parses free-text supplier payment terms (e.g. "NET 30", "net30", "Due on Receipt")
 * into a number of net days and computes invoice due dates.
 */
public with sharing class PaymentTerms {

    @TestVisible
    private static final Integer MAX_NET_DAYS = 180;

    // "NET" followed by optional whitespace and 1 to 3 digits, e.g. NET 30 / NET30 / NET  45
    private static final Pattern NET_PATTERN = Pattern.compile('^NET\\s*(\\d{1,3})$');

    // "DUE ON RECEIPT", tolerant of repeated whitespace between the words
    private static final Pattern DUE_ON_RECEIPT_PATTERN = Pattern.compile('^DUE\\s+ON\\s+RECEIPT$');

    /**
     * Returns the number of net days represented by the given payment terms.
     *
     * @param terms free-text payment terms
     * @return net days (0 for "DUE ON RECEIPT")
     * @throws UnsupportedTermsException if the terms are null, blank or not recognised
     * @throws TermsOutOfRangeException  if the net days exceed 180
     */
    public static Integer parseNetDays(String terms) {
        if (String.isBlank(terms)) {
            throw unsupported(terms);
        }

        String normalized = terms.trim().toUpperCase();

        if (DUE_ON_RECEIPT_PATTERN.matcher(normalized).matches()) {
            return 0;
        }

        Matcher netMatcher = NET_PATTERN.matcher(normalized);
        if (netMatcher.matches()) {
            Integer days = Integer.valueOf(netMatcher.group(1));
            if (days > MAX_NET_DAYS) {
                throw new TermsOutOfRangeException('Net days out of range: ' + days);
            }
            return days;
        }

        throw unsupported(terms);
    }

    /**
     * Returns the invoice due date: invoiceDate plus the net days parsed from terms.
     *
     * @param invoiceDate the invoice date
     * @param terms       free-text payment terms
     * @return invoiceDate + net days
     * @throws UnsupportedTermsException if the terms are null, blank or not recognised
     * @throws TermsOutOfRangeException  if the net days exceed 180
     * @throws IllegalArgumentException  if invoiceDate is null
     */
    public static Date dueDate(Date invoiceDate, String terms) {
        Integer netDays = parseNetDays(terms);
        if (invoiceDate == null) {
            throw new IllegalArgumentException('invoiceDate must not be null');
        }
        return invoiceDate.addDays(netDays);
    }

    private static UnsupportedTermsException unsupported(String originalTerms) {
        String shown = originalTerms == null ? 'null' : originalTerms;
        return new UnsupportedTermsException('Unsupported payment terms: ' + shown);
    }
}
