/**
 * Generic, injection-safe record search used by the admin "record finder" component.
 *
 * All object / field names are resolved through the Schema describe (so they are
 * case-insensitive and validated), filter values are passed as bind variables, and the
 * query runs in USER_MODE so record sharing and field-level security of the running
 * user are always enforced by the platform.
 */
public with sharing class RecordSearchService {

    /** Single exception type surfaced to callers for every validation / query problem. */
    public class SearchException extends Exception {}

    private static final Integer MIN_ROWS = 1;
    private static final Integer MAX_ROWS = 200;

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        // ---- Object -------------------------------------------------------------------
        Schema.DescribeSObjectResult objDescribe = describeObject(objectApiName);
        if (!objDescribe.isAccessible() || !objDescribe.isQueryable()) {
            throw new SearchException(
                'You do not have access to query object "' + objDescribe.getName() + '".'
            );
        }

        // ---- Simple argument validation ---------------------------------------------------
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('At least one field must be requested.');
        }
        if (maxRows == null || maxRows < MIN_ROWS || maxRows > MAX_ROWS) {
            throw new SearchException(
                'maxRows must be between ' + MIN_ROWS + ' and ' + MAX_ROWS + '.'
            );
        }

        Map<String, Schema.SObjectField> fieldMap = objDescribe.fields.getMap();
        String objectName = objDescribe.getName();

        // ---- SELECT clause ------------------------------------------------------------------
        List<String> selectFields = new List<String>{ 'Id' };
        Set<String> selected = new Set<String>{ 'id' };
        for (String requested : fields) {
            Schema.DescribeFieldResult fd = describeField(fieldMap, objectName, requested, 'select');
            String key = fd.getName().toLowerCase();
            if (selected.add(key)) {
                selectFields.add(fd.getName());
            }
        }

        // ---- WHERE clause -------------------------------------------------------------------
        List<String> conditions = new List<String>();
        Map<String, Object> binds = new Map<String, Object>();
        if (filters != null && !filters.isEmpty()) {
            Integer bindIndex = 0;
            for (String filterField : filters.keySet()) {
                Schema.DescribeFieldResult fd = describeField(fieldMap, objectName, filterField, 'filter');
                if (!fd.isFilterable()) {
                    throw new SearchException(
                        'Field "' + fd.getName() + '" on object "' + objectName + '" cannot be filtered.'
                    );
                }
                Object value = filters.get(filterField);
                if (value == null) {
                    // "= null" is a literal keyword; nothing user-supplied is concatenated.
                    conditions.add(fd.getName() + ' = null');
                } else {
                    String bindName = 'v' + bindIndex++;
                    binds.put(bindName, value);
                    conditions.add(fd.getName() + ' = :' + bindName);
                }
            }
        }

        // ---- ORDER BY clause ----------------------------------------------------------------
        String orderByClause = '';
        if (String.isNotBlank(orderByField)) {
            Schema.DescribeFieldResult fd = describeField(fieldMap, objectName, orderByField, 'order by');
            if (!fd.isSortable()) {
                throw new SearchException(
                    'Field "' + fd.getName() + '" on object "' + objectName + '" cannot be sorted.'
                );
            }
            orderByClause = ' ORDER BY ' + fd.getName() + ' ASC';
        }

        // ---- Assemble & run -----------------------------------------------------------------
        String soql = 'SELECT ' + String.join(selectFields, ', ')
            + ' FROM ' + objectName
            + (conditions.isEmpty() ? '' : ' WHERE ' + String.join(conditions, ' AND '))
            + orderByClause
            + ' LIMIT ' + String.valueOf(maxRows);

        try {
            return Database.queryWithBinds(soql, binds, AccessLevel.USER_MODE);
        } catch (SearchException e) {
            throw e;
        } catch (Exception e) {
            throw new SearchException('Search failed: ' + e.getMessage(), e);
        }
    }

    // ------------------------------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------------------------------

    private static Schema.DescribeSObjectResult describeObject(String objectApiName) {
        if (String.isBlank(objectApiName)) {
            throw new SearchException('Object API name is required.');
        }
        List<Schema.DescribeSObjectResult> results;
        try {
            results = Schema.describeSObjects(new List<String>{ objectApiName.trim() });
        } catch (Exception e) {
            throw new SearchException('Object "' + objectApiName + '" does not exist.');
        }
        if (results == null || results.isEmpty() || results[0] == null) {
            throw new SearchException('Object "' + objectApiName + '" does not exist.');
        }
        return results[0];
    }

    /**
     * Resolves a field name case-insensitively against the object's field map and verifies the
     * running user can read it. Throws SearchException for unknown or inaccessible fields.
     */
    private static Schema.DescribeFieldResult describeField(
        Map<String, Schema.SObjectField> fieldMap,
        String objectName,
        String fieldName,
        String usage
    ) {
        if (String.isBlank(fieldName)) {
            throw new SearchException('A blank field name was supplied in the ' + usage + ' list.');
        }
        Schema.SObjectField token = fieldMap.get(fieldName.trim().toLowerCase());
        if (token == null) {
            throw new SearchException(
                'Field "' + fieldName + '" is not a field of object "' + objectName + '".'
            );
        }
        Schema.DescribeFieldResult fd = token.getDescribe();
        if (!fd.isAccessible()) {
            throw new SearchException(
                'You do not have read access to field "' + fd.getName() + '" on object "' + objectName + '".'
            );
        }
        return fd;
    }
