/**
 * Flow-invocable action that looks up an existing Contact by email address.
 *
 * - One Result per Request, in request order.
 * - Email matching is case-insensitive and ignores leading/trailing whitespace.
 * - When several Contacts share an email, the earliest created one is returned.
 * - Bulk-safe: a single SOQL query per invocation regardless of batch size.
 * - Runs in the context of the running user's sharing rules and field-level security.
 */
public with sharing class ContactLookupAction {

    @InvocableMethod(
        label='Find Contact by Email'
        description='Finds an existing Contact by email address (case-insensitive). Returns the earliest created match.'
        category='Contact'
    )
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();
        if (requests == null || requests.isEmpty()) {
            return results;
        }

        // Normalise inputs once and collect the distinct emails to query.
        List<String> normalizedEmails = new List<String>();
        Set<String> emailsToQuery = new Set<String>();
        for (Request req : requests) {
            String normalized = normalize(req == null ? null : req.email);
            normalizedEmails.add(normalized);
            if (normalized != null) {
                emailsToQuery.add(normalized);
            }
        }

        // Single query; ordered so that the first row per email is the earliest created.
        Map<String, Id> contactIdByEmail = new Map<String, Id>();
        if (!emailsToQuery.isEmpty()) {
            for (Contact c : [
                SELECT Id, Email
                FROM Contact
                WHERE Email IN :emailsToQuery
                WITH USER_MODE
                ORDER BY CreatedDate ASC, Id ASC
            ]) {
                String key = normalize(c.Email);
                if (key != null && !contactIdByEmail.containsKey(key)) {
                    contactIdByEmail.put(key, c.Id);
                }
            }
        }

        // Build one Result per Request, preserving order.
        for (String normalized : normalizedEmails) {
            Result res = new Result();
            Id matchId = normalized == null ? null : contactIdByEmail.get(normalized);
            res.contactId = matchId;
            res.found = (matchId != null);
            results.add(res);
        }

        return results;
    }

    /**
     * Trims and lower-cases an email for consistent comparison.
     * Returns null for null/blank input.
     */
    private static String normalize(String email) {
        if (String.isBlank(email)) {
            return null;
        }
        return email.trim().toLowerCase();
    }

    public class Request {
        @InvocableVariable(
            label='Email'
            description='Email address of the Contact to find.'
            required=true
        )
        public String email;
    }

    public class Result {
        @InvocableVariable(
            label='Contact Id'
            description='Id of the matching Contact, or null if none was found.'
        )
        public Id contactId;

        @InvocableVariable(
            label='Found'
            description='True when a matching Contact was found.'
        )
        public Boolean found;
    }
}
