/**
 * Parses inbound e-commerce order payloads (JSON) into a typed structure and
 * builds the acknowledgement response.
 *
 * Uses JSON.deserializeUntyped because several payload keys (number, date,
 * currency) are reserved words in Apex and cannot be used as member names.
 */
public with sharing class OrderPayloadParser {

    private static final Integer MONEY_SCALE = 2;

    // ------------------------------------------------------------------
    // Public types
    // ------------------------------------------------------------------

    public class PayloadException extends Exception {}

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines = new List<Line>();
        public Decimal total = 0;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount = 0;
        public Decimal lineTotal = 0;
    }

    // ------------------------------------------------------------------
    // Public API
    // ------------------------------------------------------------------

    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Payload body is required.');
        }

        Object raw;
        try {
            raw = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Payload is not valid JSON: ' + e.getMessage());
        }

        if (!(raw instanceof Map<String, Object>)) {
            throw new PayloadException('Payload must be a JSON object.');
        }

        try {
            return parseOrder((Map<String, Object>) raw);
        } catch (PayloadException pe) {
            throw pe;
        } catch (Exception e) {
            // Guarantee that callers only ever see PayloadException.
            throw new PayloadException('Payload could not be parsed: ' + e.getMessage());
        }
    }

    public static String toAcknowledgement(Order order) {
        if (order == null) {
            throw new PayloadException('Order is required to build an acknowledgement.');
        }

        Integer lineCount = order.lines == null ? 0 : order.lines.size();
        Decimal total = order.total == null ? 0 : order.total;

        JSONGenerator gen = JSON.createGenerator(false);
        gen.writeStartObject();
        gen.writeStringField('number', order.orderNumber == null ? '' : order.orderNumber);
        gen.writeStringField('status', 'RECEIVED');
        gen.writeNumberField('lineCount', lineCount);
        gen.writeNumberField('total', total);
        gen.writeEndObject();
        return gen.getAsString();
    }

    // ------------------------------------------------------------------
    // Parsing helpers
    // ------------------------------------------------------------------

    private static Order parseOrder(Map<String, Object> root) {
        Order result = new Order();

        // number (required, non-blank)
        Object numberValue = root.get('number');
        String orderNumber = numberValue == null ? null : String.valueOf(numberValue);
        if (String.isBlank(orderNumber)) {
            throw new PayloadException('Order "number" is required.');
        }
        result.orderNumber = orderNumber;

        // date (optional, ISO yyyy-MM-dd)
        result.orderDate = parseDate(root.get('date'));

        // currency (optional)
        Object currencyValue = root.get('currency');
        result.currencyCode = currencyValue == null ? null : String.valueOf(currencyValue);

        // customer.email (optional)
        Object customerValue = root.get('customer');
        if (customerValue instanceof Map<String, Object>) {
            Object emailValue = ((Map<String, Object>) customerValue).get('email');
            result.customerEmail = emailValue == null ? null : String.valueOf(emailValue);
        }

        // lines (optional; empty list when missing/null)
        Object linesValue = root.get('lines');
        result.lines = new List<Line>();
        if (linesValue != null) {
            if (!(linesValue instanceof List<Object>)) {
                throw new PayloadException('"lines" must be a JSON array.');
            }
            Integer index = 0;
            for (Object lineValue : (List<Object>) linesValue) {
                result.lines.add(parseLine(lineValue, index));
                index++;
            }
        }

        // total
        Decimal total = 0;
        for (Line l : result.lines) {
            total += l.lineTotal;
        }
        result.total = total.setScale(MONEY_SCALE, RoundingMode.HALF_UP);

        return result;
    }

    private static Line parseLine(Object lineValue, Integer index) {
        if (!(lineValue instanceof Map<String, Object>)) {
            throw new PayloadException('Line ' + index + ' must be a JSON object.');
        }
        Map<String, Object> lineMap = (Map<String, Object>) lineValue;
        Line line = new Line();

        // sku (required)
        Object skuValue = lineMap.get('sku');
        String sku = skuValue == null ? null : String.valueOf(skuValue);
        if (String.isBlank(sku)) {
            throw new PayloadException('Line ' + index + ': "sku" is required.');
        }
        line.sku = sku;

        // quantity (required, positive integer)
        Object quantityValue = lineMap.get('quantity');
        if (quantityValue == null) {
            throw new PayloadException('Line ' + index + ': "quantity" is required.');
        }
        Decimal quantityDecimal = toDecimal(quantityValue, 'Line ' + index + ': "quantity"');
        if (quantityDecimal <= 0) {
            throw new PayloadException('Line ' + index + ': "quantity" must be positive.');
        }
        if (quantityDecimal.stripTrailingZeros().scale() > 0) {
            throw new PayloadException('Line ' + index + ': "quantity" must be a whole number.');
        }
        line.quantity = quantityDecimal.intValue();

        // unitPrice (required, non-negative)
        Object unitPriceValue = lineMap.get('unitPrice');
        if (unitPriceValue == null) {
            throw new PayloadException('Line ' + index + ': "unitPrice" is required.');
        }
        Decimal unitPrice = toDecimal(unitPriceValue, 'Line ' + index + ': "unitPrice"');
        if (unitPrice < 0) {
            throw new PayloadException('Line ' + index + ': "unitPrice" must not be negative.');
        }
        line.unitPrice = unitPrice;

        // discount (optional fraction, defaults to 0)
        Object discountValue = lineMap.get('discount');
        Decimal discount = discountValue == null
            ? 0
            : toDecimal(discountValue, 'Line ' + index + ': "discount"');
        line.discount = discount;

        // lineTotal = quantity x unitPrice x (1 - discount), HALF_UP to 2 dp
        Decimal rawTotal = quantityDecimal * unitPrice * (1 - discount);
        line.lineTotal = rawTotal.setScale(MONEY_SCALE, RoundingMode.HALF_UP);

        return line;
    }

    private static Date parseDate(Object value) {
        if (value == null) {
            return null;
        }
        String text = String.valueOf(value).trim();
        if (String.isBlank(text)) {
            return null;
        }
        try {
            // Date.valueOf accepts ISO yyyy-MM-dd (and yyyy-MM-dd HH:mm:ss).
            return Date.valueOf(text);
        } catch (Exception e) {
            throw new PayloadException('"date" must be in yyyy-MM-dd format: ' + text);
        }
    }

    private static Decimal toDecimal(Object value, String label) {
        if (value instanceof Decimal) {
            return (Decimal) value;
        }
        if (value instanceof Integer) {
            return Decimal.valueOf((Integer) value);
        }
        if (value instanceof Long) {
            return Decimal.valueOf((Long) value);
        }
        if (value instanceof Double) {
            return Decimal.valueOf((Double) value);
        }
        throw new PayloadException(label + ' must be a JSON number.');
    }
}
