/**
 * Imports Leads uploaded from trade-show spreadsheets.
 *
 * - Partial success: every insertable lead is inserted even if others fail.
 * - Blank LeadSource defaults to "Web".
 * - Duplicate e-mails within one call (case-insensitive, trimmed) are rejected before DML;
 *   only the first occurrence is sent to the database.
 * - A single DML statement is issued per call.
 * - Runs with the sharing rules of the current user.
 */
public with sharing class LeadImportService {

    private static final String DEFAULT_LEAD_SOURCE = 'Web';
    private static final String DUPLICATE_EMAIL_PREFIX = 'Duplicate email in import: ';
    private static final String NULL_LEAD_ERROR = 'Lead record is null';
    private static final String ERROR_SEPARATOR = '; ';

    /**
     * Per-call outcome of an import. Members are never null.
     */
    public class ImportResult {
        public Integer successCount;                // number of leads inserted
        public List<Id> insertedIds;                // Ids of the inserted leads, in input order
        public Map<Integer, String> errorsByIndex;  // input position (0-based) -> error message

        public ImportResult() {
            this.successCount = 0;
            this.insertedIds = new List<Id>();
            this.errorsByIndex = new Map<Integer, String>();
        }
    }

    /**
     * Inserts the given leads, applying defaults and in-call duplicate e-mail detection.
     *
     * @param leads leads to import, in spreadsheet order (may be null or empty)
     * @return ImportResult describing successes and per-row errors
     */
    public static ImportResult importLeads(List<Lead> leads) {
        ImportResult result = new ImportResult();

        if (leads == null || leads.isEmpty()) {
            return result;
        }

        List<Lead> leadsToInsert = new List<Lead>();
        List<Integer> inputIndexByInsertPosition = new List<Integer>();
        Set<String> seenEmails = new Set<String>();

        for (Integer i = 0; i < leads.size(); i++) {
            Lead currentLead = leads[i];

            if (currentLead == null) {
                result.errorsByIndex.put(i, NULL_LEAD_ERROR);
                continue;
            }

            if (String.isBlank(currentLead.LeadSource)) {
                currentLead.LeadSource = DEFAULT_LEAD_SOURCE;
            }

            String normalizedEmail = normalizeEmail(currentLead.Email);
            if (normalizedEmail != null) {
                if (seenEmails.contains(normalizedEmail)) {
                    result.errorsByIndex.put(i, DUPLICATE_EMAIL_PREFIX + normalizedEmail);
                    continue;
                }
                seenEmails.add(normalizedEmail);
            }

            leadsToInsert.add(currentLead);
            inputIndexByInsertPosition.add(i);
        }

        if (leadsToInsert.isEmpty()) {
            return result;
        }

        // Single DML statement, partial success allowed.
        List<Database.SaveResult> saveResults = Database.insert(leadsToInsert, false);

        for (Integer j = 0; j < saveResults.size(); j++) {
            Database.SaveResult saveResult = saveResults[j];
            Integer inputIndex = inputIndexByInsertPosition[j];

            if (saveResult.isSuccess()) {
                result.successCount++;
                result.insertedIds.add(saveResult.getId());
            } else {
                result.errorsByIndex.put(inputIndex, joinErrors(saveResult.getErrors()));
            }
        }

        return result;
    }

    /**
     * Returns the trimmed, lower-cased e-mail, or null when the e-mail is blank.
     */
    private static String normalizeEmail(String email) {
        if (String.isBlank(email)) {
            return null;
        }
        return email.trim().toLowerCase();
    }

    /**
     * Joins all database error messages for a record with "; ".
     */
    private static String joinErrors(List<Database.Error> errors) {
        List<String> messages = new List<String>();
        if (errors != null) {
            for (Database.Error err : errors) {
                messages.add(err.getMessage());
            }
        }
        return String.join(messages, ERROR_SEPARATOR);
    }
}
