/**
 * Utility that returns the active picklist values of any picklist / multi-select
 * picklist field, resolved dynamically at runtime via the Schema describe API.
 */
public with sharing class PicklistService {

    /** A single active picklist entry. */
    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault == true;
        }
    }

    /** Raised for any invalid input (blank names, unknown object/field, non-picklist field). */
    public class PicklistServiceException extends Exception {}

    /**
     * Returns the active values of the given picklist (or multi-select picklist) field,
     * in the order they are defined on the field.
     *
     * @param objectApiName  object API name (case-insensitive), standard or custom
     * @param fieldApiName   field API name (case-insensitive), standard or custom
     * @throws PicklistServiceException when inputs are blank, the object or field does
     *         not exist, or the field is not a picklist / multi-select picklist
     */
    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName)) {
            throw new PicklistServiceException('Object API name is required.');
        }
        if (String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Field API name is required.');
        }

        String objName = objectApiName.trim();
        String fldName = fieldApiName.trim();

        Schema.DescribeSObjectResult objDescribe = describeObject(objName);
        Schema.DescribeFieldResult fieldDescribe = describeField(objDescribe, objName, fldName);

        Schema.DisplayType type = fieldDescribe.getType();
        if (type != Schema.DisplayType.PICKLIST && type != Schema.DisplayType.MULTIPICKLIST) {
            throw new PicklistServiceException(
                'Field ' + objName + '.' + fldName + ' is not a picklist or multi-select picklist (type: ' + type + ').'
            );
        }

        List<Option> options = new List<Option>();
        List<Schema.PicklistEntry> entries = fieldDescribe.getPicklistValues();
        if (entries != null) {
            for (Schema.PicklistEntry entry : entries) {
                if (entry.isActive()) {
                    options.add(new Option(entry.getValue(), entry.getLabel(), entry.isDefaultValue()));
                }
            }
        }
        return options;
    }

    private static Schema.DescribeSObjectResult describeObject(String objName) {
        List<Schema.DescribeSObjectResult> results;
        try {
            // describeSObjects is case-insensitive and throws for unknown objects.
            results = Schema.describeSObjects(new List<String>{ objName });
        } catch (Exception e) {
            throw new PicklistServiceException('Object ' + objName + ' does not exist.');
        }
        if (results == null || results.isEmpty() || results[0] == null) {
            throw new PicklistServiceException('Object ' + objName + ' does not exist.');
        }
        return results[0];
    }

    private static Schema.DescribeFieldResult describeField(
        Schema.DescribeSObjectResult objDescribe, String objName, String fldName
    ) {
        Map<String, Schema.SObjectField> fieldMap = objDescribe.fields.getMap();
        Schema.SObjectField token = fieldMap.get(fldName);

        if (token == null) {
            // Defensive fallback in case the map lookup is case-sensitive in some context.
            for (String key : fieldMap.keySet()) {
                if (key.equalsIgnoreCase(fldName)) {
                    token = fieldMap.get(key);
                    break;
                }
            }
        }

        if (token == null) {
            throw new PicklistServiceException(
                'Field ' + fldName + ' does not exist on object ' + objName + '.'
            );
        }
        return token.getDescribe();
    }
}
