/**
 * Re-rates Accounts from AnnualRevenue in chunks of 200, chaining itself until every Id
 * supplied to start() has been processed.
 *
 * Why AsyncOptions.MaximumQueueableStackDepth:
 *  - Developer Edition / Trial orgs default to a chained-queueable depth of 5, and Apex
 *    tests do not run chained jobs unless a stack depth has been declared for the chain.
 *    start() declares a depth large enough for the whole list, so the same chaining code
 *    runs identically in production and in a single Test.startTest()/Test.stopTest() block.
 */
public with sharing class AccountScoringJob implements Queueable {

    @TestVisible
    private static final Integer BATCH_SIZE = 200;

    private static final Decimal HOT_THRESHOLD  = 1000000;
    private static final Decimal WARM_THRESHOLD = 100000;

    private static final String RATING_HOT  = 'Hot';
    private static final String RATING_WARM = 'Warm';
    private static final String RATING_COLD = 'Cold';

    private final List<Id> accountIds;

    /**
     * @param accountIds Ids still to be processed by this job and its successors.
     */
    public AccountScoringJob(List<Id> accountIds) {
        // Defensive copy so the caller's list can never be mutated by this job.
        this.accountIds = accountIds == null ? new List<Id>() : new List<Id>(accountIds);
    }

    /**
     * Enqueues the first job of the chain.
     *
     * @param accountIds up to 50,000 Account Ids to re-rate
     * @return the AsyncApexJob Id of the first job, or null when there is nothing to do
     */
    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }

        // Number of executions needed = ceil(size / BATCH_SIZE); +1 gives a safety margin
        // so the last job never sits exactly on the depth limit.
        Integer jobsNeeded = (accountIds.size() + BATCH_SIZE - 1) / BATCH_SIZE;

        AsyncOptions options = new AsyncOptions();
        options.MaximumQueueableStackDepth = jobsNeeded + 1;

        return System.enqueueJob(new AccountScoringJob(accountIds), options);
    }

    /**
     * Processes the first 200 Ids (one SOQL, one DML) and chains a new job for the rest.
     * Does not use the context parameter, so it is safe to call as execute(null).
     */
    public void execute(QueueableContext context) {
        if (accountIds.isEmpty()) {
            return;
        }

        List<Id> currentBatch = new List<Id>();
        List<Id> remaining    = new List<Id>();
        for (Integer i = 0; i < accountIds.size(); i++) {
            if (i < BATCH_SIZE) {
                currentBatch.add(accountIds[i]);
            } else {
                remaining.add(accountIds[i]);
            }
        }

        // Single SOQL query for this execution.
        List<Account> accounts = [
            SELECT Id, AnnualRevenue, Rating
            FROM Account
            WHERE Id IN :currentBatch
            WITH USER_MODE
        ];

        for (Account acc : accounts) {
            acc.Rating = rate(acc.AnnualRevenue);
        }

        // Single DML statement for this execution.
        if (!accounts.isEmpty()) {
            Database.update(accounts, AccessLevel.USER_MODE);
        }

        // Chain the next link. The maximum stack depth declared in start() applies to the
        // whole chain, so no special-casing for tests is needed or wanted.
        if (!remaining.isEmpty()) {
            System.enqueueJob(new AccountScoringJob(remaining));
        }
    }

    /**
     * Maps AnnualRevenue to a Rating picklist value.
     * >= 1,000,000 -> Hot, >= 100,000 -> Warm, otherwise (including null) -> Cold.
     */
    @TestVisible
    private static String rate(Decimal annualRevenue) {
        if (annualRevenue == null) {
            return RATING_COLD;
        }
        if (annualRevenue >= HOT_THRESHOLD) {
            return RATING_HOT;
        }
        if (annualRevenue >= WARM_THRESHOLD) {
            return RATING_WARM;
        }
        return RATING_COLD;
    }
}
