File: force-app/main/default/classes/ErpSyncFinalizer.cls
```apex
/**
 * Finalizer for ErpAccountSyncJob.
 * Logs every run into FB_Job_Log__c and re-enqueues the job (up to MAX_ATTEMPTS)
 * when the parent job failed.
 */
public with sharing class ErpSyncFinalizer implements Finalizer {

    public static final String JOB_NAME = 'ErpAccountSyncJob';
    public static final String STATUS_SUCCESS = 'Success';
    public static final String STATUS_FAILED = 'Failed';
    public static final Integer MAX_ATTEMPTS = 3;
    private static final Integer ERROR_MAX_LENGTH = 255;

    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds == null ? new Set<Id>() : new Set<Id>(accountIds);
        this.attempt = (attempt == null || attempt < 1) ? 1 : attempt;
    }

    public void execute(FinalizerContext ctx) {
        ParentJobResult result = ctx == null ? null : ctx.getResult();
        Boolean succeeded = result == ParentJobResult.SUCCESS;

        FB_Job_Log__c log = new FB_Job_Log__c(
            Job_Name__c = JOB_NAME,
            Attempt__c = attempt,
            Status__c = succeeded ? STATUS_SUCCESS : STATUS_FAILED
        );

        if (!succeeded) {
            Exception jobException = ctx == null ? null : ctx.getException();
            String message = jobException == null ? null : jobException.getMessage();
            if (String.isBlank(message)) {
                message = 'Unknown error';
            }
            log.Error__c = message.left(ERROR_MAX_LENGTH);
        }

        // Log first so the run is recorded even if the retry cannot be enqueued.
        insert log;

        if (!succeeded && attempt < MAX_ATTEMPTS) {
            System.enqueueJob(new ErpAccountSyncJob(accountIds, attempt + 1));
        }
    }
}
