/**
 * Nightly purge of FB_Integration_Log__c records.
 *
 * Retention rules:
 *  - Logs whose Level__c is 'ERROR' are kept for 180 days.
 *  - Every other log (DEBUG, INFO, blank, ...) is kept for 30 days.
 *
 * The class is Schedulable (so it can run every night) and Batchable (so it can
 * purge any volume of records without hitting governor limits). The scheduled
 * run deletes what fits in a single transaction and, if more expired logs remain,
 * hands the rest over to a batch job.
 */
public with sharing class LogPurgeJob implements Schedulable, Database.Batchable<SObject> {

    public static final String JOB_NAME = 'Log purge (nightly)';
    /** Every day at 02:00 (seconds minutes hours day-of-month month day-of-week). */
    public static final String CRON_NIGHTLY_2AM = '0 0 2 * * ?';
    public static final Integer DEFAULT_RETENTION_DAYS = 30;
    public static final Integer ERROR_RETENTION_DAYS = 180;

    private static final Integer BATCH_SIZE = 2000;
    private static final String ERROR_LEVEL = 'ERROR';

    private static final String SELECT_EXPIRED_LOGS =
        'SELECT Id FROM FB_Integration_Log__c ' +
        'WHERE (Level__c = :errorLevel AND CreatedDate < :errorCutoff) ' +
        '   OR ((Level__c != :errorLevel OR Level__c = null) AND CreatedDate < :defaultCutoff)';

    public LogPurgeJob() {
    }

    /**
     * Schedules the purge to run every day at 02:00 under the name "Log purge (nightly)".
     * @return the CronTrigger Id returned by System.schedule
     */
    public static Id scheduleNightly() {
        return System.schedule(JOB_NAME, CRON_NIGHTLY_2AM, new LogPurgeJob());
    }

    // ---------------------------------------------------------------------
    // Schedulable
    // ---------------------------------------------------------------------

    public void execute(SchedulableContext sc) {
        Map<String, Object> binds = bindVariables();

        // Delete as much as this transaction allows, then hand the remainder to a batch job.
        Integer capacity = Limits.getLimitDmlRows() - Limits.getDmlRows();
        if (capacity > 0) {
            binds.put('rowLimit', capacity);
            List<FB_Integration_Log__c> expired = (List<FB_Integration_Log__c>) Database.queryWithBinds(
                SELECT_EXPIRED_LOGS + ' LIMIT :rowLimit',
                binds,
                AccessLevel.USER_MODE
            );
            purge(expired);
        }

        binds.put('rowLimit', 1);
        List<FB_Integration_Log__c> remaining = (List<FB_Integration_Log__c>) Database.queryWithBinds(
            SELECT_EXPIRED_LOGS + ' LIMIT :rowLimit',
            binds,
            AccessLevel.USER_MODE
        );
        if (!remaining.isEmpty()) {
            Database.executeBatch(new LogPurgeJob(), BATCH_SIZE);
        }
    }

    // ---------------------------------------------------------------------
    // Database.Batchable
    // ---------------------------------------------------------------------

    public Database.QueryLocator start(Database.BatchableContext bc) {
        return Database.getQueryLocatorWithBinds(SELECT_EXPIRED_LOGS, bindVariables(), AccessLevel.USER_MODE);
    }

    public void execute(Database.BatchableContext bc, List<SObject> scope) {
        purge((List<FB_Integration_Log__c>) scope);
    }

    public void finish(Database.BatchableContext bc) {
        // Nothing to do; the next nightly run picks up anything that could not be deleted.
    }

    // ---------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------

    private static Map<String, Object> bindVariables() {
        Datetime now = Datetime.now();
        return new Map<String, Object>{
            'errorLevel'    => ERROR_LEVEL,
            'errorCutoff'   => now.addDays(-ERROR_RETENTION_DAYS),
            'defaultCutoff' => now.addDays(-DEFAULT_RETENTION_DAYS)
        };
    }

    private static void purge(List<FB_Integration_Log__c> logs) {
        if (logs == null || logs.isEmpty()) {
            return;
        }
        if (!Schema.SObjectType.FB_Integration_Log__c.isDeletable()) {
            throw new LogPurgeException('The running user is not allowed to delete FB_Integration_Log__c records.');
        }

        // Partial success: one locked/failed row must not stop the purge of the others.
        List<Database.DeleteResult> results = Database.delete(logs, false);

        List<FB_Integration_Log__c> deleted = new List<FB_Integration_Log__c>();
        for (Integer i = 0; i < results.size(); i++) {
            if (results[i].isSuccess()) {
                deleted.add(logs[i]);
            } else {
                System.debug(LoggingLevel.WARN,
                    'LogPurgeJob: could not delete ' + logs[i].Id + ': ' + results[i].getErrors());
            }
        }

        // Free the storage straight away instead of waiting for the recycle bin to expire.
        if (!deleted.isEmpty()) {
            Database.emptyRecycleBin(deleted);
        }
    }

    public class LogPurgeException extends Exception {
    }
