/**
 * Central fflib Application factory wiring for the org.
 *
 * NOTE: static field initialisation order matters. The Domain factory depends on the
 * Selector factory, so Selector must be declared (and therefore initialised) before Domain.
 */
public inherited sharing class Application {

    // Unit of Work factory - SObject types listed in dependency (insert) order:
    // Accounts first, then Contacts and Opportunities (both look up to Account),
    // then OpportunityContactRoles (look up to Opportunity and Contact).
    public static final fflib_Application.UnitOfWorkFactory UnitOfWork =
        new fflib_Application.UnitOfWorkFactory(
            new List<SObjectType>{
                Account.SObjectType,
                Contact.SObjectType,
                Opportunity.SObjectType,
                OpportunityContactRole.SObjectType
            }
        );

    // Service factory - maps service interfaces to their implementations
    public static final fflib_Application.ServiceFactory Service =
        new fflib_Application.ServiceFactory(
            new Map<Type, Type>{
                IAccountsService.class => AccountsServiceImpl.class
            }
        );

    // Selector factory - maps SObject types to their selector classes
    public static final fflib_Application.SelectorFactory Selector =
        new fflib_Application.SelectorFactory(
            new Map<SObjectType, Type>{
                Account.SObjectType => AccountsSelector.class,
                Contact.SObjectType => ContactsSelector.class
            }
        );

    // Domain factory - maps SObject types to their domain constructor classes.
    // Uses the Selector factory above so newInstance(Set<Id>) queries via the registered selectors.
    public static final fflib_Application.DomainFactory Domain =
        new fflib_Application.DomainFactory(
            Application.Selector,
            new Map<SObjectType, Type>{
                Account.SObjectType => Accounts.Constructor.class
            }
        );
}
