/**
 * Account domain class built on the newer fflib_SObjects structure.
 * This is a plain collection of Account records; trigger handling lives elsewhere.
 */
public inherited sharing class Accounts extends fflib_SObjects implements IAccounts {

    // ---------------------------------------------------------------------
    // Factory methods (always go through Application.Domain so unit tests can
    // substitute the domain with Application.Domain.setMock)
    // ---------------------------------------------------------------------

    public static IAccounts newInstance(List<Account> records) {
        return (IAccounts) Application.Domain.newInstance(records, Schema.Account.SObjectType);
    }

    public static IAccounts newInstance(Set<Id> accountIds) {
        // The domain factory loads the records through the configured selector
        return (IAccounts) Application.Domain.newInstance(accountIds);
    }

    // ---------------------------------------------------------------------
    // Constructors
    // ---------------------------------------------------------------------

    public Accounts(List<SObject> records) {
        super(toAccountList(records), Schema.Account.SObjectType);
    }

    // ---------------------------------------------------------------------
    // IAccounts implementation
    // ---------------------------------------------------------------------

    public List<Account> getAccounts() {
        return (List<Account>) getRecords();
    }

    public IAccounts selectByRating(String rating) {
        List<Account> matches = new List<Account>();
        for (Account record : getAccounts()) {
            if (record.Rating == rating) {
                matches.add(record);
            }
        }
        return new Accounts(matches);
    }

    public Set<Id> getOwnerIds() {
        Set<Id> ownerIds = new Set<Id>();
        for (Account record : getAccounts()) {
            if (record.OwnerId != null) {
                ownerIds.add(record.OwnerId);
            }
        }
        return ownerIds;
    }

    public void setRating(String rating) {
        for (Account record : getAccounts()) {
            record.Rating = rating;
        }
    }

    // ---------------------------------------------------------------------
    // Domain factory constructor
    // ---------------------------------------------------------------------

    public class Constructor implements fflib_IDomainConstructor {
        public fflib_IDomain construct(List<Object> objects) {
            return new Accounts((List<SObject>) objects);
        }
    }

    // ---------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------

    /**
     * Ensures the records held by the domain are always a strongly typed
     * List<Account>, regardless of whether the caller supplied a List<Account>
     * or a generic List<SObject> (e.g. from the domain factory).
     */
    private static List<Account> toAccountList(List<SObject> records) {
        if (records == null) {
            return new List<Account>();
        }
        if (records instanceof List<Account>) {
            return (List<Account>) records;
        }
        List<Account> accounts = new List<Account>();
        for (SObject record : records) {
            accounts.add((Account) record);
        }
        return accounts;
    }
}
