public with sharing class CaseEscalationService {

    public class EscalationException extends Exception {}

    private static final String CLOSED_STATUS = 'Closed';
    private static final String HIGH_PRIORITY = 'High';

    public static void escalate(Set<Id> caseIds, String reason) {
        if (String.isBlank(reason)) {
            throw new EscalationException('An escalation reason is required.');
        }
        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        List<Case> cases = CasesSelector.newInstance().selectById(caseIds);

        List<Case> casesToUpdate = new List<Case>();
        List<Task> tasksToInsert = new List<Task>();
        Date tomorrow = Date.today().addDays(1);

        for (Case c : cases) {
            if (c.Status == CLOSED_STATUS || c.IsEscalated == true) {
                continue;
            }

            c.IsEscalated = true;
            c.Priority = HIGH_PRIORITY;
            casesToUpdate.add(c);

            tasksToInsert.add(new Task(
                Subject = 'Escalated: ' + reason,
                WhatId = c.Id,
                OwnerId = c.OwnerId,
                ActivityDate = tomorrow,
                Priority = HIGH_PRIORITY
            ));
        }

        if (casesToUpdate.isEmpty()) {
            return;
        }

        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();
        for (Case c : casesToUpdate) {
            uow.registerDirty(c);
        }
        for (Task t : tasksToInsert) {
            uow.registerNew(t);
        }
        uow.commitWork();
    }
}
