/**
 * Service layer class responsible for onboarding Accounts together with their Contacts.
 *
 * All DML is delegated to a single fflib_SObjectUnitOfWork so that the work is committed
 * in one bulk-safe transaction (one insert per SObjectType regardless of record volume).
 */
public with sharing class AccountOnboardingService {

    public class AccountOnboardingException extends Exception {}

    /**
     * Creates one Account per map key and one Contact per last name in the corresponding
     * list, linking every Contact to its newly created Account.
     *
     * @param contactLastNamesByAccountName  Account Name => list of Contact last names
     * @return the newly inserted Accounts (Ids populated); empty list when input is null/empty
     */
    public static List<Account> createAccountsWithContacts(
        Map<String, List<String>> contactLastNamesByAccountName
    ) {
        List<Account> newAccounts = new List<Account>();

        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty()) {
            return newAccounts;
        }

        // Object-level security: fail fast rather than letting the DML fail half-way.
        if (!Schema.SObjectType.Account.isCreateable() || !Schema.SObjectType.Contact.isCreateable()) {
            throw new AccountOnboardingException(
                'Insufficient access to create Account and Contact records.'
            );
        }

        // Order matters: parents (Account) must be registered before children (Contact)
        // so the Unit of Work can resolve the AccountId relationship on commit.
        fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(
            new List<Schema.SObjectType>{
                Account.SObjectType,
                Contact.SObjectType
            }
        );

        for (String accountName : contactLastNamesByAccountName.keySet()) {
            if (String.isBlank(accountName)) {
                // Name is required on Account; skip entries that cannot produce a valid record.
                continue;
            }

            Account newAccount = new Account(Name = accountName);
            uow.registerNew(newAccount);
            newAccounts.add(newAccount);

            List<String> lastNames = contactLastNamesByAccountName.get(accountName);
            if (lastNames == null) {
                continue;
            }

            for (String lastName : lastNames) {
                if (String.isBlank(lastName)) {
                    // LastName is required on Contact; skip invalid entries.
                    continue;
                }
                Contact newContact = new Contact(LastName = lastName);
                // Registers the Contact for insert and wires Contact.AccountId to the
                // (not yet inserted) parent Account; resolved automatically at commit time.
                uow.registerNew(newContact, Contact.AccountId, newAccount);
            }
        }

        // Single commit: one bulk insert for Accounts, then one bulk insert for Contacts.
        uow.commitWork();

        // The registered Account instances now carry their Ids.
        return newAccounts;
    }
}
