/**
 * Closes opportunities as "Closed Won" and notifies Fulfilment via the Deal_Won__e platform event.
 *
 * Deal_Won__e is configured as "Publish Immediately", i.e. it is NOT rolled back with the
 * transaction. The events are therefore registered with the unit of work via
 * registerPublishAfterSuccessTransaction so that fflib only publishes them once the
 * opportunity DML has been committed successfully. If the DML fails the unit of work rolls
 * back, publishes nothing, and rethrows the exception to the caller.
 */
public with sharing class OpportunityWinService {

    @TestVisible
    private static final String STAGE_CLOSED_WON = 'Closed Won';

    /**
     * @param opportunityIds ids of the opportunities to close
     * @return the number of opportunities actually closed (those already Closed Won are skipped)
     */
    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();
        Integer closedCount = 0;

        for (Opportunity opp : OpportunitiesSelector.newInstance().selectById(opportunityIds)) {
            if (opp.StageName == STAGE_CLOSED_WON) {
                continue;
            }

            opp.StageName = STAGE_CLOSED_WON;
            opp.CloseDate = Date.today();
            uow.registerDirty(opp);

            // Only published by the UoW after the DML above has been committed successfully.
            uow.registerPublishAfterSuccessTransaction(
                new Deal_Won__e(
                    Opportunity_Id__c = opp.Id,
                    Amount__c = opp.Amount
                )
            );

            closedCount++;
        }

        if (closedCount > 0) {
            // Single commit: updates first, events only after the commit succeeded.
            uow.commitWork();
        }

        return closedCount;
    }
}
