/**
 * Normalizes Contact.Phone values so they contain only digits and the "+" sign,
 * as required by the dialer integration.
 */
public with sharing class ContactPhoneCleanup {

    // Matches every character that is NOT a digit or a plus sign.
    private static final String NON_DIALABLE_CHARS = '[^0-9+]';

    /**
     * Strips every character that is not a digit or "+" from the Phone of the given contacts
     * and saves them in a single partial-success DML call.
     *
     * @param contactIds Ids of the contacts to normalize (up to 200 per call).
     * @return Map of Contact Id -> first error message for every contact that could not be
     *         saved. Empty when all contacts were saved (or nothing needed saving).
     */
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> errorsByContactId = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return errorsByContactId;
        }

        // Deduplicate and drop null Ids before querying.
        Set<Id> idsToProcess = new Set<Id>();
        for (Id contactId : contactIds) {
            if (contactId != null) {
                idsToProcess.add(contactId);
            }
        }
        if (idsToProcess.isEmpty()) {
            return errorsByContactId;
        }

        // Contacts without a phone are excluded at query time.
        List<Contact> contactsToUpdate = new List<Contact>();
        for (Contact c : [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :idsToProcess
              AND Phone != null
            WITH USER_MODE
        ]) {
            String normalized = c.Phone.replaceAll(NON_DIALABLE_CHARS, '');
            // Only send records whose value actually changes to DML.
            if (normalized != c.Phone) {
                c.Phone = normalized;
                contactsToUpdate.add(c);
            }
        }

        if (contactsToUpdate.isEmpty()) {
            return errorsByContactId;
        }

        // Single partial-success update so one failing record does not block the rest.
        List<Database.SaveResult> results = Database.update(
            contactsToUpdate,
            false,
            AccessLevel.USER_MODE
        );

        // Results are returned in the same order as the input list; use the index rather than
        // SaveResult.getId(), which is not guaranteed to be populated for failed records.
        for (Integer i = 0; i < results.size(); i++) {
            Database.SaveResult sr = results[i];
            if (!sr.isSuccess()) {
                String message = sr.getErrors().isEmpty()
                    ? 'Unknown error'
                    : sr.getErrors()[0].getMessage();
                errorsByContactId.put(contactsToUpdate[i].Id, message);
            }
        }

        return errorsByContactId;
    }
}
