/**
 * Pipeline totals for the four open stages managed by Sales Ops.
 */
public with sharing class PipelineSummary {

    @TestVisible
    private static final List<String> STAGES = new List<String>{
        'Prospecting',
        'Qualification',
        'Proposal/Price Quote',
        'Negotiation/Review'
    };

    /**
     * Returns the sum of Amount per stage for opportunities whose CloseDate is between
     * fromDate and toDate (both inclusive). Every one of the four stages is always present
     * as a key; stages with no matching opportunities (or only null amounts) map to 0.
     */
    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        if (fromDate == null || toDate == null) {
            throw new IllegalArgumentException('fromDate and toDate are required.');
        }
        if (fromDate > toDate) {
            throw new IllegalArgumentException('fromDate must not be after toDate.');
        }

        // Seed every stage with 0 so the caller never sees a missing key or a null value.
        Map<String, Decimal> totals = new Map<String, Decimal>();
        for (String stage : STAGES) {
            totals.put(stage, 0);
        }

        List<AggregateResult> results = [
            SELECT StageName stage, SUM(Amount) total
            FROM Opportunity
            WHERE StageName IN :STAGES
              AND CloseDate >= :fromDate
              AND CloseDate <= :toDate
            WITH USER_MODE
            GROUP BY StageName
        ];

        for (AggregateResult ar : results) {
            String stage = (String) ar.get('stage');
            Decimal total = (Decimal) ar.get('total');
            // SUM is null when every matched opportunity has a null Amount.
            totals.put(stage, total == null ? 0 : total);
        }

        return totals;
    }
}
