/**
 * Sets Case.Priority = 'High' on insert when the related Account has Rating = 'Hot'.
 * Cases without an account, or with an account that is not Hot, are left untouched.
 *
 * Bulk-safe: one SOQL query for the whole batch (up to 200 cases), never a query per record.
 */
public inherited sharing class CasePriorityHandler {

    private static final String HOT_RATING = 'Hot';
    private static final String HIGH_PRIORITY = 'High';

    public static void setPriorityForHotAccounts(List<Case> newCases) {
        if (newCases == null || newCases.isEmpty()) {
            return;
        }

        // 1. Collect the distinct Account Ids from the cases that actually have one.
        Set<Id> accountIds = new Set<Id>();
        for (Case c : newCases) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return; // No accounts to check, nothing to change.
        }

        // 2. One query for the whole batch, instead of one query per case.
        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT Id, Rating FROM Account WHERE Id IN :accountIds]
        );

        // 3. Bump priority only for cases whose account is Hot.
        for (Case c : newCases) {
            if (c.AccountId == null) {
                continue;
            }
            Account acc = accountsById.get(c.AccountId);
            if (acc != null && acc.Rating == HOT_RATING) {
                c.Priority = HIGH_PRIORITY;
            }
        }
    }
}
