/**
 * Publishes Deal_Stage_Change__e platform events for opportunities so the
 * data warehouse can subscribe to stage changes.
 *
 * Bulk-safe: all events are published with a single EventBus.publish call
 * (one DML statement) regardless of how many opportunities are passed in.
 * The returned SaveResults are in the same order as the input list, so
 * results[i] corresponds to opportunities[i].
 */
public with sharing class DealEventPublisher {

    /**
     * Builds one Deal_Stage_Change__e per opportunity and publishes them.
     *
     * @param opportunities Opportunities whose stage changed (up to a full trigger batch).
     * @return One Database.SaveResult per opportunity, in input order.
     *         Empty list if no opportunities were supplied.
     */
    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        List<Database.SaveResult> results = new List<Database.SaveResult>();

        if (opportunities == null || opportunities.isEmpty()) {
            return results;
        }

        List<Deal_Stage_Change__e> events = new List<Deal_Stage_Change__e>();
        for (Opportunity opp : opportunities) {
            events.add(new Deal_Stage_Change__e(
                // Assigning an Id to a String yields the 18-character form.
                Opportunity_Id__c = String.valueOf(opp.Id),
                Stage__c          = opp.StageName,
                Amount__c         = opp.Amount
            ));
        }

        // Single publish call = one DML statement; SaveResults come back in
        // the same order as the events list, which mirrors the input order.
        results.addAll(EventBus.publish(events));

        return results;
    }
}
