/**
 * Keeps Account.Rating in sync with the account's open pipeline.
 *
 * Collects the distinct accounts affected by this transaction and hands them
 * to AccountRatingService in ONE call. Doing one @future call per opportunity
 * would exceed the 50-future-calls-per-transaction limit when the CPQ
 * integration saves 200 opportunities at a time.
 */
trigger OpportunityTrigger on Opportunity (after insert, after update) {

    Set<Id> accountIds = new Set<Id>();

    for (Opportunity opp : Trigger.new) {
        if (Trigger.isInsert) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        } else {
            Opportunity oldOpp = Trigger.oldMap.get(opp.Id);

            Boolean relevantChange =
                opp.StageName != oldOpp.StageName ||
                opp.Amount    != oldOpp.Amount    ||
                opp.AccountId != oldOpp.AccountId;

            if (relevantChange) {
                if (opp.AccountId != null) {
                    accountIds.add(opp.AccountId);
                }
                // Re-parented opportunity: the old account's pipeline changed too.
                if (oldOpp.AccountId != null && oldOpp.AccountId != opp.AccountId) {
                    accountIds.add(oldOpp.AccountId);
                }
            }
        }
    }

    if (!accountIds.isEmpty()) {
        AccountRatingService.recalculate(accountIds);
    }
}
