/**
 * Recalculates Account.Rating from the account's open opportunities:
 *   Hot  - at least one open opportunity with Amount >= 100,000
 *   Warm - open opportunities exist, but none that large
 *   Cold - no open opportunities
 *
 * Runs "without sharing" on purpose: the rating is a roll-up over ALL of the
 * account's opportunities, so it must not depend on what the saving user
 * happens to be able to see.
 */
public without sharing class AccountRatingService {

    public static final Decimal HOT_THRESHOLD = 100000;
    public static final String RATING_HOT  = 'Hot';
    public static final String RATING_WARM = 'Warm';
    public static final String RATING_COLD = 'Cold';

    /**
     * Entry point used by the trigger. Runs asynchronously when possible so
     * opportunity saves stay fast; falls back to synchronous processing when
     * we are already in an async context (a future cannot start a future).
     */
    public static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        if (System.isFuture() || System.isBatch() || System.isQueueable()) {
            recalculateNow(accountIds);
        } else {
            recalculateAsync(accountIds);
        }
    }

    /**
     * Asynchronous worker. One call handles every account touched by the
     * transaction, so a 200-record batch costs a single future call.
     */
    @future
    public static void recalculateAsync(Set<Id> accountIds) {
        recalculateNow(accountIds);
    }

    /**
     * Synchronous implementation. Safe to call directly from tests or from
     * other async jobs.
     */
    public static void recalculateNow(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // One row per account that has at least one open opportunity.
        // MAX() ignores null Amounts, so an account whose open opps all have a
        // null Amount comes back with maxAmount == null -> Warm.
        Map<Id, Decimal> maxOpenAmountByAccount = new Map<Id, Decimal>();
        for (AggregateResult ar : [
            SELECT AccountId accId, MAX(Amount) maxAmount
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND IsClosed = false
            GROUP BY AccountId
        ]) {
            maxOpenAmountByAccount.put(
                (Id) ar.get('accId'),
                (Decimal) ar.get('maxAmount')
            );
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Account acc : [
            SELECT Id, Rating
            FROM Account
            WHERE Id IN :accountIds
        ]) {
            String newRating;
            if (!maxOpenAmountByAccount.containsKey(acc.Id)) {
                newRating = RATING_COLD;
            } else {
                Decimal maxAmount = maxOpenAmountByAccount.get(acc.Id);
                newRating = (maxAmount != null && maxAmount >= HOT_THRESHOLD)
                    ? RATING_HOT
                    : RATING_WARM;
            }

            if (acc.Rating != newRating) {
                accountsToUpdate.add(new Account(Id = acc.Id, Rating = newRating));
            }
        }

        if (accountsToUpdate.isEmpty()) {
            return;
        }

        // Partial success: one account failing (e.g. a validation rule) should
        // not prevent the rest from being brought up to date.
        List<Database.SaveResult> results = Database.update(accountsToUpdate, false);
        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess()) {
                for (Database.Error err : results[i].getErrors()) {
                    System.debug(LoggingLevel.ERROR,
                        'AccountRatingService: failed to update Account ' +
                        accountsToUpdate[i].Id + ' - ' + err.getStatusCode() +
                        ': ' + err.getMessage());
                }
            }
        }
    }
}
