/**
 * Defaults OpportunityLineItem.Discount to the product's standard discount
 * when the rep did not enter one. Discount rules stay in PricingRules; this
 * class only resolves product families in bulk so no SOQL runs inside a loop.
 */
public with sharing class LineItemDiscountHandler {

    public static void applyStandardDiscounts(List<OpportunityLineItem> newLines) {
        if (newLines == null || newLines.isEmpty()) {
            return;
        }

        // 1. Pick the lines that need a default and gather the products to look up.
        List<OpportunityLineItem> linesNeedingDiscount = new List<OpportunityLineItem>();
        Set<Id> productIds = new Set<Id>();
        Set<Id> pricebookEntryIdsWithoutProduct = new Set<Id>();

        for (OpportunityLineItem line : newLines) {
            // A discount the rep typed (including 0) is always kept.
            if (line.Discount != null) {
                continue;
            }
            linesNeedingDiscount.add(line);

            if (line.Product2Id != null) {
                productIds.add(line.Product2Id);
            } else if (line.PricebookEntryId != null) {
                pricebookEntryIdsWithoutProduct.add(line.PricebookEntryId);
            }
        }

        if (linesNeedingDiscount.isEmpty()) {
            return;
        }

        // 2. Lines that only carry a PricebookEntryId: resolve the product in one query.
        Map<Id, Id> productIdByPricebookEntryId = new Map<Id, Id>();
        if (!pricebookEntryIdsWithoutProduct.isEmpty()) {
            for (PricebookEntry pbe : [
                SELECT Id, Product2Id
                FROM PricebookEntry
                WHERE Id IN :pricebookEntryIdsWithoutProduct
            ]) {
                productIdByPricebookEntryId.put(pbe.Id, pbe.Product2Id);
                productIds.add(pbe.Product2Id);
            }
        }

        if (productIds.isEmpty()) {
            return;
        }

        // 3. One query for all product families in this batch.
        Map<Id, Product2> productsById = new Map<Id, Product2>([
            SELECT Id, Family
            FROM Product2
            WHERE Id IN :productIds
        ]);

        // 4. Apply the pricing team's rules, family already in hand -> no SOQL in the loop.
        for (OpportunityLineItem line : linesNeedingDiscount) {
            Id productId = line.Product2Id != null
                ? line.Product2Id
                : productIdByPricebookEntryId.get(line.PricebookEntryId);

            Product2 product = productId == null ? null : productsById.get(productId);
            if (product == null) {
                // Product can't be resolved; leave Discount untouched for standard validation to handle.
                continue;
            }

            line.Discount = PricingRules.standardDiscountForFamily(product.Family);
        }
    }
}
