/**
 * Matches imported leads to existing contacts by email.
 *
 * Pure in-memory utility: no SOQL, no DML, no record mutation.
 * Linear time (one pass over contacts, one pass over leads) so it is safe to
 * run inside the import transaction at thousands of leads x thousands of contacts.
 */
public with sharing class LeadContactMatcher {

    /**
     * Returns a list with the same size and order as `leads`. Each element is the Id
     * of the contact whose email matches the lead's email (ignoring case and
     * leading/trailing whitespace), or null when there is no match.
     *
     * Rules:
     *  - A lead or contact with a blank email never matches.
     *  - When several contacts share an email, the first one in `contacts` order wins.
     */
    public static List<Id> matchByEmail(List<Lead> leads, List<Contact> contacts) {
        List<Id> result = new List<Id>();
        if (leads == null || leads.isEmpty()) {
            return result;
        }

        // Index contacts by normalized email once. Only the first contact per email is kept,
        // which preserves "first in contacts order" without any extra bookkeeping.
        Map<String, Id> contactIdByEmail = new Map<String, Id>();
        if (contacts != null) {
            for (Contact c : contacts) {
                if (c == null) {
                    continue;
                }
                String key = normalizeEmail(c.Email);
                if (key != null && !contactIdByEmail.containsKey(key)) {
                    contactIdByEmail.put(key, c.Id);
                }
            }
        }

        // Single pass over leads; result index i corresponds to leads[i].
        for (Lead l : leads) {
            String key = (l == null) ? null : normalizeEmail(l.Email);
            result.add(key == null ? null : contactIdByEmail.get(key));
        }

        return result;
    }

    /**
     * Trims and lower-cases an email for comparison. Returns null for blank input so
     * blank emails can never match each other.
     */
    private static String normalizeEmail(String email) {
        if (String.isBlank(email)) {
            return null;
        }
        return email.trim().toLowerCase();
    }
}
