/**
 * Case trigger. Enqueues the CSAT survey job for cases that have just been closed.
 *
 * NOTE: One Queueable is enqueued per transaction (not per case). A synchronous
 * transaction may enqueue at most 50 Queueable jobs (1 when already running async),
 * so a per-case enqueue would throw a LimitException for list-view mass closes and
 * for the nightly API job that closes up to 200 cases. Per-record isolation is
 * provided inside CaseSurveyJob via partial-success DML.
 */
trigger CaseTrigger on Case (after update) {

    if (!Trigger.isAfter || !Trigger.isUpdate) {
        return;
    }

    Set<Id> newlyClosedCaseIds = new Set<Id>();

    for (Case c : Trigger.new) {
        Case oldCase = Trigger.oldMap.get(c.Id);

        Boolean becameClosed = c.IsClosed && !oldCase.IsClosed;

        if (becameClosed && c.ContactId != null) {
            newlyClosedCaseIds.add(c.Id);
        }
    }

    if (newlyClosedCaseIds.isEmpty()) {
        return;
    }

    // Guard against the Queueable enqueue limit (e.g. when this update is itself
    // running inside another async job that has already used its allowance).
    if (Limits.getQueueableJobs() < Limits.getLimitQueueableJobs()) {
        System.enqueueJob(new CaseSurveyJob(newlyClosedCaseIds));
    } else {
        System.debug(LoggingLevel.ERROR,
            'CaseTrigger: Queueable limit reached, CSAT survey job not enqueued for cases: '
            + newlyClosedCaseIds);
    }
}
