```apex
/**
 * Asynchronously creates a CSAT survey Task for each newly closed Case that has a Contact.
 *
 * Receives a set of Case Ids (not sObjects) so the job always works on fresh data.
 * Uses partial-success DML so that a failure on one Task does not prevent the
 * other surveys from being created. Database.AllowsCallouts is implemented so the
 * planned vendor integration can be added here later.
 */
public with sharing class CaseSurveyJob implements Queueable, Database.AllowsCallouts {

    private static final String SUBJECT_PREFIX = 'CSAT survey: ';
    private static final String STATUS_NOT_STARTED = 'Not Started';
    private static final Integer DUE_IN_DAYS = 2;

    private final Set<Id> caseIds;

    public CaseSurveyJob(Set<Id> caseIds) {
        this.caseIds = caseIds == null ? new Set<Id>() : caseIds;
    }

    /** Convenience constructor for a single case. */
    public CaseSurveyJob(Id caseId) {
        this(caseId == null ? new Set<Id>() : new Set<Id>{ caseId });
    }

    public void execute(QueueableContext context) {
        if (caseIds.isEmpty()) {
            return;
        }

        List<Case> cases = [
            SELECT Id, CaseNumber, ContactId, IsClosed
            FROM Case
            WHERE Id IN :caseIds
        ];

        List<Task> surveyTasks = new List<Task>();
        Date dueDate = Date.today().addDays(DUE_IN_DAYS);

        for (Case c : cases) {
            // Re-check in case the record changed between enqueue and execution.
            if (!c.IsClosed || c.ContactId == null) {
                continue;
            }

            surveyTasks.add(new Task(
                WhatId       = c.Id,
                WhoId        = c.ContactId,
                Subject      = SUBJECT_PREFIX + c.CaseNumber,
                ActivityDate = dueDate,
                Status       = STATUS_NOT_STARTED
            ));
        }

        if (surveyTasks.isEmpty()) {
            return;
        }

        // allOrNone = false: one failing Task must not block the others.
        List<Database.SaveResult> results = Database.insert(surveyTasks, false);

        for (Integer i = 0; i < results.size(); i++) {
            Database.SaveResult sr = results[i];
            if (!sr.isSuccess()) {
                Task failed = surveyTasks[i];
                for (Database.Error err : sr.getErrors()) {
                    System.debug(LoggingLevel.ERROR,
                        'CaseSurveyJob: failed to create survey Task for Case ' + failed.WhatId
                        + ' (' + err.getStatusCode() + '): ' + err.getMessage());
                }
            }
        }
    }
}
