/**
 * Sends renewal reminder emails to the owners of the given opportunities.
 *
 * Designed to be called from a scheduled job with up to 200 opportunity Ids.
 * All messages are built first and sent with a single Messaging.sendEmail
 * call (allOrNothing = false), so one failing message does not prevent the
 * others from being delivered and the 10-invocation-per-transaction limit on
 * Messaging.sendEmail is never at risk.
 */
public inherited sharing class RenewalReminderService {

    /**
     * @param opportunityIds Ids of the opportunities whose owners should be reminded.
     * @return number of emails that were sent successfully.
     */
    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Dedupe defensively; the caller may pass the same Id twice.
        Set<Id> uniqueIds = new Set<Id>(opportunityIds);
        uniqueIds.remove(null);
        if (uniqueIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities = [
            SELECT Id, Name, CloseDate, OwnerId, Owner.IsActive
            FROM Opportunity
            WHERE Id IN :uniqueIds
        ];

        List<Messaging.SingleEmailMessage> messages = new List<Messaging.SingleEmailMessage>();
        for (Opportunity opp : opportunities) {
            // Emails to inactive users always fail; skip them rather than report errors.
            if (opp.OwnerId == null || opp.Owner.IsActive != true) {
                continue;
            }
            messages.add(buildMessage(opp));
        }

        if (messages.isEmpty()) {
            return 0;
        }

        // Single invocation; allOrNothing = false so individual failures don't block the rest.
        List<Messaging.SendEmailResult> results = Messaging.sendEmail(messages, false);

        Integer sentCount = 0;
        for (Messaging.SendEmailResult result : results) {
            if (result.isSuccess()) {
                sentCount++;
            }
        }
        return sentCount;
    }

    private static Messaging.SingleEmailMessage buildMessage(Opportunity opp) {
        Messaging.SingleEmailMessage mail = new Messaging.SingleEmailMessage();
        // Addressing an internal User by Id: does not consume the daily single-email allocation.
        mail.setTargetObjectId(opp.OwnerId);
        // Required to be false when the target is a User.
        mail.setSaveAsActivity(false);
        mail.setSubject('Renewal due: ' + opp.Name);

        String closeDateText = opp.CloseDate == null ? 'not set' : opp.CloseDate.format();
        String body =
            'Hello,\n\n' +
            'The opportunity "' + opp.Name + '" is due for renewal.\n' +
            'Close date: ' + closeDateText + '\n\n' +
            'Please review the opportunity and follow up with the customer.\n\n' +
            URL.getOrgDomainUrl().toExternalForm() + '/' + opp.Id + '\n';
        mail.setPlainTextBody(body);

        return mail;
    }
}
