import { LightningElement, api, wire } from 'lwc';
import { getRecord, getFieldValue } from 'lightning/uiRecordApi';
import NAME_FIELD from '@salesforce/schema/Account.Name';
import INDUSTRY_FIELD from '@salesforce/schema/Account.Industry';
import ANNUAL_REVENUE_FIELD from '@salesforce/schema/Account.AnnualRevenue';
import OWNER_NAME_FIELD from '@salesforce/schema/Account.Owner.Name';

const FIELDS = [NAME_FIELD, INDUSTRY_FIELD, ANNUAL_REVENUE_FIELD, OWNER_NAME_FIELD];

export default class AccountHeader extends LightningElement {
    // Provided by the record page. The wire is reactive on $recordId, so when the
    // page (e.g. a reused console tab) supplies a new id the record is reloaded.
    @api recordId;

    record;
    error;

    @wire(getRecord, { recordId: '$recordId', fields: FIELDS })
    wiredAccount({ data, error }) {
        if (data) {
            this.record = data;
            this.error = undefined;
        } else if (error) {
            this.error = error;
            this.record = undefined;
        } else {
            // Wire reset (e.g. recordId changed to undefined) – back to loading state
            this.record = undefined;
            this.error = undefined;
        }
    }

    get isLoading() {
        return !this.record && !this.error;
    }

    get hasError() {
        return !!this.error;
    }

    get hasData() {
        return !!this.record;
    }

    get name() {
        return getFieldValue(this.record, NAME_FIELD);
    }

    get industry() {
        return getFieldValue(this.record, INDUSTRY_FIELD);
    }

    get hasIndustry() {
        const value = this.industry;
        return value !== undefined && value !== null && value !== '';
    }

    get annualRevenue() {
        return getFieldValue(this.record, ANNUAL_REVENUE_FIELD);
    }

    get ownerName() {
        return getFieldValue(this.record, OWNER_NAME_FIELD);
    }

    get errorMessage() {
        if (!this.error) {
            return '';
        }
        const body = this.error.body;
        if (Array.isArray(body)) {
            return body.map((e) => e.message).join(', ');
        }
        if (body && typeof body.message === 'string') {
            return body.message;
        }
        if (typeof this.error.message === 'string') {
            return this.error.message;
        }
        return 'Unknown error';
    }
}
