import { NavigationMixin } from 'lightning/navigation';
import { encodeDefaultFieldValues } from 'lightning/pageReferenceUtils';

const CASE_LIST_FILTER = 'My_Open_Cases';

export default class AccountQuickLinks extends NavigationMixin(LightningElement) {
    @api recordId;

    casesUrl;
    casesPageRef = {
        type: 'standard__objectPage',
        attributes: {
            objectApiName: 'Case',
            actionName: 'list'
        },
        state: {
            filterName: CASE_LIST_FILTER
        }
    };

    connectedCallback() {
        this[NavigationMixin.GenerateUrl](this.casesPageRef)
            .then((url) => {
                this.casesUrl = url;
            })
            .catch(() => {
                this.casesUrl = undefined;
            });
    }

    get newContactPageRef() {
        return {
            type: 'standard__objectPage',
            attributes: {
                objectApiName: 'Contact',
                actionName: 'new'
            },
            state: {
                defaultFieldValues: encodeDefaultFieldValues({
                    AccountId: this.recordId
                })
            }
        };
    }

    get contactsRelatedListPageRef() {
        return {
            type: 'standard__recordRelationshipPage',
            attributes: {
                recordId: this.recordId,
                objectApiName: 'Account',
                relationshipApiName: 'Contacts',
                actionName: 'view'
            }
        };
    }

    get editAccountPageRef() {
        return {
            type: 'standard__recordPage',
            attributes: {
                recordId: this.recordId,
                objectApiName: 'Account',
                actionName: 'edit'
            }
        };
    }

    handleClick(event) {
        const action = event.currentTarget.dataset.action;
        let pageRef;
        switch (action) {
            case 'new-contact':
                pageRef = this.newContactPageRef;
                break;
            case 'contacts':
                pageRef = this.contactsRelatedListPageRef;
                break;
            case 'edit':
                pageRef = this.editAccountPageRef;
                break;
            default:
                return;
        }
        this[NavigationMixin.Navigate](pageRef);
    }

    handleCasesClick(event) {
        // Let the navigation service handle it instead of a full page load
        event.preventDefault();
        this[NavigationMixin.Navigate](this.casesPageRef);
    }
}
