import { LightningElement, api } from 'lwc';

/**
 * Reusable WAI-ARIA disclosure (collapsible section).
 *
 * Usage:
 *   <c-collapsible-section>
 *       <span slot="title">Billing details</span>
 *       <p>Body content…</p>
 *   </c-collapsible-section>
 */
export default class CollapsibleSection extends LightningElement {
    /** Internal expansion state; the section starts collapsed. */
    _expanded = false;

    /**
     * Public, read/write expansion state so parents can open/close programmatically
     * (e.g. <c-collapsible-section expanded>). Defaults to collapsed.
     */
    @api
    get expanded() {
        return this._expanded;
    }
    set expanded(value) {
        this._expanded = value === true || value === 'true' || value === '';
    }

    /** `aria-expanded` must be the string "true" / "false". */
    get ariaExpandedValue() {
        return this._expanded ? 'true' : 'false';
    }

    /** `hidden` is a boolean attribute: present when collapsed, absent when expanded. */
    get isCollapsed() {
        return !this._expanded;
    }

    handleToggle() {
        this._expanded = !this._expanded;
        this.dispatchEvent(
            new CustomEvent('toggle', {
                detail: { expanded: this._expanded }
            })
        );
    }
}
