import { LightningElement, api } from 'lwc';

export default class AccountContactList extends LightningElement {
    /**
     * Array of contact records ({ Id, Name, Title }) owned by the parent.
     * This component never mutates it; sorting is done on a shallow copy.
     */
    @api contacts;

    get hasContacts() {
        return Array.isArray(this.contacts) && this.contacts.length > 0;
    }

    get contactCount() {
        return this.hasContacts ? this.contacts.length : 0;
    }

    get countLabel() {
        const count = this.contactCount;
        return count === 1 ? '1 contact' : `${count} contacts`;
    }

    get sortedContacts() {
        if (!this.hasContacts) {
            return [];
        }
        // Copy before sorting so the parent's array is never mutated.
        return [...this.contacts].sort((a, b) =>
            (a.Name || '').localeCompare(b.Name || '')
        );
    }
}
