import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_DELAY_MS = 300;
const MIN_SEARCH_LENGTH = 2;

export default class ContactSearch extends LightningElement {
    contacts = [];
    error;

    _searchTerm = '';
    _debounceTimer;
    _latestRequestId = 0;

    get errorMessage() {
        if (!this.error) {
            return '';
        }
        if (this.error.body && this.error.body.message) {
            return this.error.body.message;
        }
        return this.error.message || 'Unknown error';
    }

    handleChange(event) {
        const rawValue = event.target.value;
        this._searchTerm = (rawValue || '').trim();

        // Any new keystroke invalidates a pending (not yet fired) search.
        this._cancelPendingSearch();

        if (this._searchTerm.length < MIN_SEARCH_LENGTH) {
            // Invalidate in-flight responses so they cannot repopulate results.
            this._latestRequestId++;
            this.contacts = [];
            this.error = undefined;
            return;
        }

        this._debounceTimer = setTimeout(() => {
            this._debounceTimer = undefined;
            this._search(this._searchTerm);
        }, DEBOUNCE_DELAY_MS);
    }

    disconnectedCallback() {
        // Component removed: make sure a pending debounced search never fires,
        // and ignore any in-flight responses.
        this._cancelPendingSearch();
        this._latestRequestId++;
    }

    _cancelPendingSearch() {
        if (this._debounceTimer) {
            clearTimeout(this._debounceTimer);
            this._debounceTimer = undefined;
        }
    }

    _search(searchTerm) {
        const requestId = ++this._latestRequestId;

        searchContacts({ searchTerm })
            .then((result) => {
                if (requestId !== this._latestRequestId) {
                    // Stale response (out of order) – ignore.
                    return;
                }
                this.contacts = result || [];
                this.error = undefined;
            })
            .catch((error) => {
                if (requestId !== this._latestRequestId) {
                    return;
                }
                this.error = error;
                this.contacts = [];
            });
    }
}
