import { LightningElement, api } from 'lwc';
import getOpenOpportunities from '@salesforce/apex/OpportunityController.getOpenOpportunities';

export default class OpenOpportunities extends LightningElement {
    @api recordId;

    isLoading = false;
    opportunities = [];
    error;

    connectedCallback() {
        this.loadOpportunities();
    }

    handleRetry() {
        this.loadOpportunities();
    }

    get hasOpportunities() {
        return Array.isArray(this.opportunities) && this.opportunities.length > 0;
    }

    get errorMessage() {
        if (!this.error) {
            return '';
        }
        if (this.error.body && this.error.body.message) {
            return this.error.body.message;
        }
        if (this.error.message) {
            return this.error.message;
        }
        return 'Unknown error';
    }

    loadOpportunities() {
        this.isLoading = true;
        this.error = undefined;

        getOpenOpportunities({ accountId: this.recordId })
            .then((result) => {
                this.opportunities = result || [];
                this.error = undefined;
            })
            .catch((error) => {
                this.opportunities = [];
                this.error = error;
            })
            .finally(() => {
                this.isLoading = false;
            });
    }
}
