import { LightningElement, api } from 'lwc';
import { NavigationMixin } from 'lightning/navigation';
import { deleteRecord } from 'lightning/uiRecordApi';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import LightningConfirm from 'lightning/confirm';

const COLUMNS = [
    { label: 'Name', fieldName: 'Name' },
    { label: 'Stage', fieldName: 'StageName' },
    { label: 'Amount', fieldName: 'Amount', type: 'currency' },
    {
        type: 'action',
        typeAttributes: {
            rowActions: [
                { label: 'View', name: 'view' },
                { label: 'Edit', name: 'edit' },
                { label: 'Delete', name: 'delete' }
            ]
        }
    }
];

export default class OpportunityActionsTable extends NavigationMixin(LightningElement) {
    columns = COLUMNS;

    // Internal copy of the rows rendered in the datatable. We never mutate the
    // parent's array; deletes operate on this copy only.
    rows = [];

    _opportunities = [];

    @api
    get opportunities() {
        return this._opportunities;
    }
    set opportunities(value) {
        this._opportunities = value;
        this.rows = Array.isArray(value) ? [...value] : [];
    }

    handleRowAction(event) {
        const actionName = event.detail.action.name;
        const row = event.detail.row;

        switch (actionName) {
            case 'view':
                this.navigateToRecord(row.Id, 'view');
                break;
            case 'edit':
                this.navigateToRecord(row.Id, 'edit');
                break;
            case 'delete':
                this.confirmAndDelete(row);
                break;
            default:
                break;
        }
    }

    navigateToRecord(recordId, actionName) {
        this[NavigationMixin.Navigate]({
            type: 'standard__recordPage',
            attributes: {
                recordId,
                objectApiName: 'Opportunity',
                actionName
            }
        });
    }

    async confirmAndDelete(row) {
        const confirmed = await LightningConfirm.open({
            message: `Are you sure you want to delete "${row.Name}"? This cannot be undone.`,
            variant: 'header',
            label: 'Delete Opportunity',
            theme: 'warning'
        });

        if (!confirmed) {
            // User cancelled: do nothing.
            return;
        }

        try {
            await deleteRecord(row.Id);

            // Remove the row from our internal copy only (parent array untouched).
            this.rows = this.rows.filter((r) => r.Id !== row.Id);

            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Opportunity deleted',
                    message: `${row.Name} was deleted.`,
                    variant: 'success'
                })
            );
        } catch (error) {
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Delete failed',
                    message: this.reduceErrorMessage(error),
                    variant: 'error'
                })
            );
        }
    }

    reduceErrorMessage(error) {
        if (error && error.body) {
            if (Array.isArray(error.body)) {
                return error.body.map((e) => e.message).join(', ');
            }
            if (error.body.message) {
                return error.body.message;
            }
        }
        return (error && error.message) || 'Unknown error';
    }
}
