import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const REFRESH_INTERVAL_MS = 60 * 1000;

export default class QueueMonitor extends LightningElement {
    stats;
    error;

    _intervalId = null;
    _inFlight = false;
    // Incremented on every connect/disconnect so that responses from a
    // previous "life" of the component are ignored and cannot block
    // or corrupt the current polling loop.
    _generation = 0;

    connectedCallback() {
        this._generation += 1;
        this._inFlight = false;
        document.addEventListener('visibilitychange', this.handleVisibilityChange);

        // Only poll while the page is visible. If the console is in a background
        // tab, the visibilitychange listener will start polling when it is shown.
        if (document.visibilityState !== 'hidden') {
            this.startPolling();
        }
    }

    disconnectedCallback() {
        document.removeEventListener('visibilitychange', this.handleVisibilityChange);
        this.stopPolling();
        // Invalidate any request still in flight so it does not touch state
        // or interfere with a later re-insertion of the component.
        this._generation += 1;
        this._inFlight = false;
    }

    // Arrow function so the same reference is used for add/removeEventListener.
    handleVisibilityChange = () => {
        if (document.visibilityState === 'hidden') {
            this.stopPolling();
        } else {
            // Page became visible again: load immediately, then every 60 seconds.
            this.startPolling();
        }
    };

    startPolling() {
        // Guarantee only one polling loop exists at a time.
        this.stopPolling();
        this.loadStats();
        this._intervalId = setInterval(() => this.loadStats(), REFRESH_INTERVAL_MS);
    }

    stopPolling() {
        if (this._intervalId !== null) {
            clearInterval(this._intervalId);
            this._intervalId = null;
        }
    }

    async loadStats() {
        // Skip this refresh if a request is still in flight or the page is hidden.
        if (this._inFlight || document.visibilityState === 'hidden') {
            return;
        }

        const generation = this._generation;
        this._inFlight = true;

        try {
            const result = await getQueueStats();
            if (generation !== this._generation) {
                return; // stale response from a previous lifecycle
            }
            this.stats = result;
            this.error = undefined;
        } catch (e) {
            if (generation !== this._generation) {
                return;
            }
            this.error =
                e && e.body && e.body.message
                    ? e.body.message
                    : (e && e.message) || 'Unknown error';
            // Keep existing stats (if any) and keep polling.
        } finally {
            if (generation === this._generation) {
                this._inFlight = false;
            }
        }
    }
}
