import { LightningElement } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import register from '@salesforce/apex/RegistrationController.register';

const BLOCKED_DOMAINS = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];
const WORK_EMAIL_MESSAGE = 'Use your work email address.';

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';
    isSaving = false;

    handleChange(event) {
        const field = event.target.dataset.field;
        const value = event.detail.value;
        if (field === 'fullName') {
            this.fullName = value;
        } else if (field === 'email') {
            this.email = value;
        } else if (field === 'company') {
            this.company = value;
        }
    }

    isBlockedDomain(email) {
        if (!email || typeof email !== 'string') {
            return false;
        }
        const atIndex = email.lastIndexOf('@');
        if (atIndex < 0) {
            return false;
        }
        const domain = email.substring(atIndex + 1).trim().toLowerCase();
        return BLOCKED_DOMAINS.includes(domain);
    }

    async handleRegister() {
        const inputs = [...this.template.querySelectorAll('lightning-input')];
        const emailInput = inputs.find((input) => input.dataset.field === 'email');

        // Step 1: custom work-email validation, before reporting validity.
        if (emailInput) {
            if (this.isBlockedDomain(this.email)) {
                emailInput.setCustomValidity(WORK_EMAIL_MESSAGE);
            } else {
                emailInput.setCustomValidity('');
            }
        }

        // Step 2: report validity on every input (no short-circuit so all messages show).
        const allValid = inputs.reduce((valid, input) => {
            const inputValid = input.reportValidity();
            return valid && inputValid;
        }, true);

        // Step 3: stop if anything is invalid.
        if (!allValid) {
            return;
        }

        this.isSaving = true;
        try {
            await register({
                fullName: this.fullName,
                email: this.email,
                company: this.company
            });
            // Step 4: success toast.
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registered',
                    message: 'Your registration was successful.',
                    variant: 'success'
                })
            );
        } catch (error) {
            const message =
                (error && error.body && error.body.message) ||
                (error && error.message) ||
                'Unknown error';
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Registration failed',
                    message,
                    variant: 'error'
                })
            );
        } finally {
            this.isSaving = false;
        }
    }
}
