import { LightningElement, api } from 'lwc';

const NAV_KEYS = new Set(['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' ']);

export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];
    _value;
    // null means "follow the selected value (or first option)"
    _activeIndex = null;

    @api
    get options() {
        return this._options;
    }
    set options(val) {
        this._options = Array.isArray(val) ? val : [];
        this._activeIndex = null;
    }

    @api
    get value() {
        return this._value;
    }
    set value(val) {
        this._value = val;
        // Parent changed the selection: active option moves to it.
        this._activeIndex = null;
    }

    get selectedIndex() {
        return this._options.findIndex((opt) => opt.value === this._value);
    }

    get activeIndex() {
        if (this._options.length === 0) {
            return -1;
        }
        if (this._activeIndex !== null && this._activeIndex >= 0 && this._activeIndex < this._options.length) {
            return this._activeIndex;
        }
        const selected = this.selectedIndex;
        return selected >= 0 ? selected : 0;
    }

    optionId(index) {
        return `option-${index}`;
    }

    get activeDescendant() {
        const idx = this.activeIndex;
        return idx >= 0 ? this.optionId(idx) : undefined;
    }

    get items() {
        const active = this.activeIndex;
        return this._options.map((opt, index) => {
            const isSelected = opt.value === this._value;
            const isActive = index === active;
            return {
                key: opt.value,
                id: this.optionId(index),
                value: opt.value,
                label: opt.label,
                ariaSelected: isSelected ? 'true' : 'false',
                className:
                    'slds-listbox__item option' +
                    (isSelected ? ' is-selected' : '') +
                    (isActive ? ' is-active' : '')
            };
        });
    }

    handleKeydown(event) {
        const key = event.key;
        if (!NAV_KEYS.has(key)) {
            return; // keep default behaviour (e.g. Tab)
        }
        event.preventDefault();

        const count = this._options.length;
        if (count === 0) {
            return;
        }
        const current = this.activeIndex;

        switch (key) {
            case 'ArrowDown':
                this._activeIndex = Math.min(current + 1, count - 1);
                break;
            case 'ArrowUp':
                this._activeIndex = Math.max(current - 1, 0);
                break;
            case 'Home':
                this._activeIndex = 0;
                break;
            case 'End':
                this._activeIndex = count - 1;
                break;
            case 'Enter':
            case ' ':
                this.selectIndex(current);
                break;
            default:
                break;
        }
    }

    handleOptionClick(event) {
        const clickedValue = event.currentTarget.dataset.value;
        const index = this._options.findIndex((opt) => String(opt.value) === clickedValue);
        if (index >= 0) {
            this.selectIndex(index);
        }
    }

    selectIndex(index) {
        if (index < 0 || index >= this._options.length) {
            return;
        }
        this._activeIndex = index;
        const newValue = this._options[index].value;
        if (newValue === this._value) {
            return; // already selected: nothing to dispatch
        }
        this._value = newValue;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: newValue }
            })
        );
    }
}
