import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    @api heading;

    _tasks = [];
    items = [];
    newLabel = '';
    nextId = 1;

    /**
     * Initial list from the parent. The component works on its own deep copy
     * so the parent's array and task objects are never mutated. Whenever the
     * parent assigns a new array, the internal list is replaced by a copy of it.
     */
    @api
    get tasks() {
        return this._tasks;
    }
    set tasks(value) {
        this._tasks = value;
        this.items = Array.isArray(value)
            ? value.map((task) => ({ id: task.id, label: task.label, done: !!task.done }))
            : [];
    }

    // Display-only transformation: the public `heading` value is left untouched
    // and later changes by the parent are reflected automatically.
    get displayHeading() {
        return this.heading ? String(this.heading).toUpperCase() : '';
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const label = (this.newLabel || '').trim();
        if (!label) {
            return;
        }

        const id = this.generateUniqueId();

        // Reassign to a new array so the change is reactive and we never
        // mutate shared state.
        this.items = [...this.items, { id, label, done: false }];
        this.newLabel = '';

        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label } }));
    }

    handleToggle(event) {
        const id = event.target.dataset.id;
        // Replace the toggled task with a new object (immutable update) so the
        // template and the `remaining` getter re-evaluate.
        this.items = this.items.map((task) =>
            task.id === id ? { ...task, done: !task.done } : task
        );
    }

    generateUniqueId() {
        const existing = new Set(this.items.map((task) => String(task.id)));
        let id = `new-${this.nextId++}`;
        while (existing.has(id)) {
            id = `new-${this.nextId++}`;
        }
        return id;
    }
}
