/**
 * Sets each contact's current employer using NPSP's standard mechanism:
 * the Contact.npsp__Primary_Affiliation__c lookup.
 *
 * NPSP's Affiliation trigger handlers (TDTM) react to a change of that lookup by
 *  - creating (or re-using) a Current, primary npe5__Affiliation__c between the contact
 *    and the organization, and
 *  - marking the previous primary affiliation Former / non-primary with an end date of today.
 *
 * This class therefore never touches npe5__Affiliation__c directly and never touches
 * Contact.AccountId, so the contact stays in its household account. Contacts whose
 * primary affiliation already points to the requested organization are skipped, which
 * avoids duplicate affiliations and unnecessary DML.
 *
 * Governor footprint for any map size (tested to 200 contacts): 1 SOQL query, 1 DML.
 */
public with sharing class EmployerService {

    /**
     * @param employerByContactId  Contact Id -> Organization Account Id of the current employer.
     *                             A null or empty map is a no-op.
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // Only consider well-formed entries (non-null contact and organization Ids).
        Set<Id> contactIds = new Set<Id>();
        for (Id contactId : employerByContactId.keySet()) {
            if (contactId != null && employerByContactId.get(contactId) != null) {
                contactIds.add(contactId);
            }
        }
        if (contactIds.isEmpty()) {
            return;
        }

        // 1 SOQL: read the contacts' current primary affiliation so we only update what changed.
        List<Contact> contacts = [
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :contactIds
            WITH USER_MODE
        ];

        List<Contact> contactsToUpdate = new List<Contact>();
        for (Contact c : contacts) {
            Id newEmployerId = employerByContactId.get(c.Id);
            // Already the primary affiliation -> nothing to do (no duplicate affiliation).
            if (c.npsp__Primary_Affiliation__c == newEmployerId) {
                continue;
            }
            contactsToUpdate.add(new Contact(
                Id = c.Id,
                npsp__Primary_Affiliation__c = newEmployerId
            ));
        }

        if (contactsToUpdate.isEmpty()) {
            return;
        }

        // 1 DML: NPSP's TDTM handlers create the new Current/primary affiliation and
        // close out the previous primary one (Former, non-primary, End Date = today).
        Database.update(contactsToUpdate, AccessLevel.USER_MODE);
    }
}
