/**
 * Records monthly giving sign-ups as NPSP Enhanced Recurring Donations (RD2).
 *
 * Only the Recurring Donation records are inserted; NPSP's own RD2 automation
 * creates the installment Opportunities from the schedule we define here.
 */
public with sharing class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    // Enhanced Recurring Donations picklist values
    @TestVisible private static final String INSTALLMENT_PERIOD_MONTHLY = 'Monthly';
    @TestVisible private static final String RECURRING_TYPE_OPEN  = 'Open';
    @TestVisible private static final String RECURRING_TYPE_FIXED = 'Fixed';
    @TestVisible private static final String STATUS_ACTIVE = 'Active';
    @TestVisible private static final String DAY_OF_MONTH_LAST_DAY = 'Last_Day';
    private static final Integer LAST_DAY_FORM_VALUE = 31;

    /**
     * Creates one Enhanced Recurring Donation per request.
     * @return the new Recurring Donation Ids, in the same order as the requests
     * @throws RecurringGiftException if any request is invalid (no DML is performed)
     */
    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        List<Id> newIds = new List<Id>();
        if (requests == null || requests.isEmpty()) {
            return newIds;
        }

        // Validate everything before touching the database
        for (Integer i = 0; i < requests.size(); i++) {
            validate(requests[i], i);
        }

        if (!Schema.SObjectType.npe03__Recurring_Donation__c.isCreateable()) {
            throw new RecurringGiftException(
                'You do not have permission to create Recurring Donations.');
        }

        List<npe03__Recurring_Donation__c> rds = new List<npe03__Recurring_Donation__c>();
        for (GiftRequest req : requests) {
            rds.add(buildRecurringDonation(req));
        }

        // Single DML; NPSP triggers generate the installment Opportunities
        insert rds;

        for (npe03__Recurring_Donation__c rd : rds) {
            newIds.add(rd.Id);
        }
        return newIds;
    }

    private static void validate(GiftRequest req, Integer index) {
        if (req == null) {
            throw new RecurringGiftException('Request at index ' + index + ' is null.');
        }
        if (req.contactId == null) {
            throw new RecurringGiftException('Request at index ' + index + ': contact is required.');
        }
        if (req.contactId.getSobjectType() != Contact.SObjectType) {
            throw new RecurringGiftException('Request at index ' + index + ': contactId must be a Contact Id.');
        }
        if (req.amount == null || req.amount <= 0) {
            throw new RecurringGiftException('Request at index ' + index + ': amount must be greater than zero.');
        }
        if (req.dayOfMonth == null || req.dayOfMonth < 1 || req.dayOfMonth > 31) {
            throw new RecurringGiftException('Request at index ' + index + ': dayOfMonth must be between 1 and 31.');
        }
        if (req.startDate == null) {
            throw new RecurringGiftException('Request at index ' + index + ': startDate is required.');
        }
        if (req.installments != null && req.installments < 0) {
            throw new RecurringGiftException('Request at index ' + index + ': installments cannot be negative.');
        }
    }

    private static npe03__Recurring_Donation__c buildRecurringDonation(GiftRequest req) {
        Boolean isFixed = req.installments != null && req.installments > 0;

        npe03__Recurring_Donation__c rd = new npe03__Recurring_Donation__c(
            npe03__Contact__c              = req.contactId,
            npe03__Amount__c               = req.amount,
            npe03__Installment_Period__c   = INSTALLMENT_PERIOD_MONTHLY,
            npsp__InstallmentFrequency__c  = 1,
            npsp__Day_of_Month__c          = toDayOfMonthValue(req.dayOfMonth),
            npsp__StartDate__c             = req.startDate,
            npsp__Status__c                = STATUS_ACTIVE,
            npsp__PaymentMethod__c         = req.paymentMethod,
            npsp__RecurringType__c         = isFixed ? RECURRING_TYPE_FIXED : RECURRING_TYPE_OPEN
        );

        if (isFixed) {
            rd.npe03__Installments__c = req.installments;
        }
        return rd;
    }

    /**
     * The form's "31" means "last day of the month"; Enhanced Recurring Donations
     * models that with its own Day of Month picklist value rather than the day 31
     * (or the legacy Always Use Last Day Of Month checkbox).
     */
    private static String toDayOfMonthValue(Integer dayOfMonth) {
        return dayOfMonth == LAST_DAY_FORM_VALUE ? DAY_OF_MONTH_LAST_DAY : String.valueOf(dayOfMonth);
    }
}
