/**
 * Service for splitting an Opportunity across General Accounting Units by percentage.
 *
 * Allocations are created as PERCENT-based allocations (npsp__Percent__c populated, npsp__Amount__c left
 * blank). NPSP's allocation trigger handler (ALLO_Allocations_TDTM) derives the amount from the percent and,
 * because the percent is stored on the record, automatically recalculates the amount whenever the
 * Opportunity Amount changes later. That is what keeps a 60/40 split correct when a $1,000 gift is
 * corrected to $2,000 ($1,200 / $800) without any additional code.
 */
public with sharing class GauAllocationService {

    public class AllocationException extends Exception {}

    private static final Decimal MAX_TOTAL_PERCENT = 100;

    /**
     * Replaces every existing GAU Allocation on the Opportunity with one percent-based allocation per map entry.
     *
     * @param opportunityId    Opportunity to allocate
     * @param percentByGauId   npsp__General_Accounting_Unit__c Id => percentage (60 means 60%)
     * @return the inserted allocations
     * @throws AllocationException when input is invalid or a GAU is inactive / not found
     */
    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        // ---------- 1. Validate everything before touching data ----------
        validateInput(opportunityId, percentByGauId);
        validateOpportunityExists(opportunityId);
        validateGausActive(percentByGauId.keySet());

        // ---------- 2. Build new allocations ----------
        List<npsp__Allocation__c> newAllocations = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            newAllocations.add(new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = percentByGauId.get(gauId)
                // npsp__Amount__c intentionally left null: NPSP computes it from Percent and keeps it in sync
            ));
        }

        // ---------- 3. Replace existing allocations atomically ----------
        Savepoint sp = Database.setSavepoint();
        try {
            List<npsp__Allocation__c> existing = [
                SELECT Id
                FROM npsp__Allocation__c
                WHERE npsp__Opportunity__c = :opportunityId
                WITH USER_MODE
            ];
            if (!existing.isEmpty()) {
                Database.delete(existing, AccessLevel.USER_MODE);
            }
            Database.insert(newAllocations, AccessLevel.USER_MODE);
        } catch (Exception e) {
            Database.rollback(sp);
            throw new AllocationException(
                'Unable to allocate Opportunity ' + opportunityId + ': ' + e.getMessage(), e
            );
        }

        return newAllocations;
    }

    // ------------------------------------------------------------------
    // Validation helpers
    // ------------------------------------------------------------------

    private static void validateInput(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        if (opportunityId == null) {
            throw new AllocationException('An Opportunity Id is required.');
        }
        if (opportunityId.getSobjectType() != Opportunity.SObjectType) {
            throw new AllocationException('Id ' + opportunityId + ' is not an Opportunity Id.');
        }
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('At least one GAU percentage is required.');
        }

        Decimal total = 0;
        for (Id gauId : percentByGauId.keySet()) {
            if (gauId == null || gauId.getSobjectType() != npsp__General_Accounting_Unit__c.SObjectType) {
                throw new AllocationException('Invalid General Accounting Unit Id: ' + gauId);
            }
            Decimal pct = percentByGauId.get(gauId);
            if (pct == null || pct <= 0) {
                throw new AllocationException(
                    'Percentage for GAU ' + gauId + ' must be greater than 0 (received ' + pct + ').'
                );
            }
            total += pct;
        }
        if (total > MAX_TOTAL_PERCENT) {
            throw new AllocationException(
                'Total allocation percentage (' + total + '%) cannot exceed ' + MAX_TOTAL_PERCENT + '%.'
            );
        }
    }

    private static void validateOpportunityExists(Id opportunityId) {
        Integer count = [
            SELECT COUNT()
            FROM Opportunity
            WHERE Id = :opportunityId
            WITH USER_MODE
        ];
        if (count == 0) {
            throw new AllocationException('Opportunity ' + opportunityId + ' was not found or is not accessible.');
        }
    }

    private static void validateGausActive(Set<Id> gauIds) {
        Map<Id, npsp__General_Accounting_Unit__c> gaus = new Map<Id, npsp__General_Accounting_Unit__c>([
            SELECT Id, Name, npsp__Active__c
            FROM npsp__General_Accounting_Unit__c
            WHERE Id IN :gauIds
            WITH USER_MODE
        ]);

        List<String> problems = new List<String>();
        for (Id gauId : gauIds) {
            npsp__General_Accounting_Unit__c gau = gaus.get(gauId);
            if (gau == null) {
                problems.add('GAU ' + gauId + ' was not found or is not accessible.');
            } else if (gau.npsp__Active__c != true) {
                problems.add('GAU "' + gau.Name + '" (' + gauId + ') is inactive.');
            }
        }
        if (!problems.isEmpty()) {
            throw new AllocationException(String.join(problems, ' '));
        }
    }
}
