/**
 * Converts an open NPSP donation (pledge) into a schedule of monthly installment payments.
 *
 * Paid and written-off payments are treated as history and are never touched. Every other
 * (open) payment of the opportunity is replaced by `numberOfPayments` new unpaid payments
 * that together add up exactly to the outstanding amount of the opportunity.
 */
public with sharing class PaymentPlanService {

    public class PaymentPlanException extends Exception {}

    private static final Integer CURRENCY_SCALE = 2;

    /**
     * @param opportunityId    Opportunity (donation) to schedule.
     * @param numberOfPayments Number of monthly installments to create (>= 1).
     * @param firstPaymentDate Scheduled date of the first installment; defaults to today when null.
     * @return The newly inserted payments in schedule order.
     */
    public static List<npe01__OppPayment__c> scheduleInstallments(
        Id opportunityId,
        Integer numberOfPayments,
        Date firstPaymentDate
    ) {
        // ---- Validation (before any DML so nothing changes on failure) ----
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException('numberOfPayments must be at least 1.');
        }
        if (opportunityId == null) {
            throw new PaymentPlanException('opportunityId is required.');
        }
        Date startDate = firstPaymentDate == null ? Date.today() : firstPaymentDate;

        List<Opportunity> opps = [
            SELECT Id, Amount, IsClosed,
                (SELECT Id, npe01__Payment_Amount__c, npe01__Paid__c, npe01__Written_Off__c
                 FROM npe01__OppPayment__r)
            FROM Opportunity
            WHERE Id = :opportunityId
            WITH USER_MODE
            LIMIT 1
        ];
        if (opps.isEmpty()) {
            throw new PaymentPlanException('Opportunity ' + opportunityId + ' was not found or is not accessible.');
        }
        Opportunity opp = opps[0];

        if (opp.IsClosed) {
            throw new PaymentPlanException('Installments cannot be scheduled for a closed opportunity.');
        }

        // ---- Split existing payments into history (keep) and open (replace) ----
        Decimal historicalTotal = 0;
        List<npe01__OppPayment__c> paymentsToDelete = new List<npe01__OppPayment__c>();
        for (npe01__OppPayment__c pmt : opp.npe01__OppPayment__r) {
            Boolean isPaid = pmt.npe01__Paid__c == true;
            Boolean isWrittenOff = pmt.npe01__Written_Off__c == true;
            if (isPaid || isWrittenOff) {
                historicalTotal += (pmt.npe01__Payment_Amount__c == null ? 0 : pmt.npe01__Payment_Amount__c);
            } else {
                paymentsToDelete.add(pmt);
            }
        }

        Decimal oppAmount = opp.Amount == null ? 0 : opp.Amount;
        Decimal outstanding = (oppAmount - historicalTotal).setScale(CURRENCY_SCALE, RoundingMode.HALF_UP);
        if (outstanding <= 0) {
            throw new PaymentPlanException(
                'The outstanding amount (' + outstanding + ') must be greater than zero to schedule installments.'
            );
        }

        // ---- Build the installment schedule ----
        Decimal installment = outstanding.divide(numberOfPayments, CURRENCY_SCALE, RoundingMode.DOWN);
        Decimal lastInstallment = outstanding - (installment * (numberOfPayments - 1));

        List<npe01__OppPayment__c> newPayments = new List<npe01__OppPayment__c>();
        for (Integer i = 0; i < numberOfPayments; i++) {
            Boolean isLast = (i == numberOfPayments - 1);
            newPayments.add(new npe01__OppPayment__c(
                npe01__Opportunity__c = opp.Id,
                npe01__Payment_Amount__c = isLast ? lastInstallment : installment,
                npe01__Scheduled_Date__c = startDate.addMonths(i),
                npe01__Paid__c = false,
                npe01__Written_Off__c = false
            ));
        }

        // ---- Apply changes atomically ----
        Savepoint sp = Database.setSavepoint();
        try {
            if (!paymentsToDelete.isEmpty()) {
                Database.delete(paymentsToDelete, true, AccessLevel.USER_MODE);
            }
            Database.insert(newPayments, true, AccessLevel.USER_MODE);
        } catch (Exception e) {
            Database.rollback(sp);
            throw new PaymentPlanException('Unable to schedule installments: ' + e.getMessage(), e);
        }

        return newPayments;
    }
}
