/**
 * Records a received gift (Closed Won donation) for a Contact in an NPSP org using the
 * Household Account model with NPSP Payments enabled.
 *
 * NPSP automation (TDTM) reacts to the Opportunity insert: it typically creates the primary
 * contact role from npsp__Primary_Contact__c, the "Household Member" roles for the other
 * household members and an automatic Payment for a Closed Won gift. Because those behaviours
 * are configurable, this service does not blindly insert roles/payments; it inserts the
 * Opportunity and then reconciles the resulting records so that the final state is exactly:
 *   - one "Donor" (primary) contact role for the donor,
 *   - one "Household Member" role for every other household member,
 *   - exactly one paid payment for the full amount dated on the gift date.
 */
public with sharing class GiftService {

    @TestVisible private static final String DONOR_ROLE = 'Donor';
    @TestVisible private static final String HOUSEHOLD_MEMBER_ROLE = 'Household Member';
    private static final String DEFAULT_CLOSED_WON_STAGE = 'Closed Won';

    /**
     * Records a Closed Won donation of amount from the contact, closed on giftDate.
     * @return the Id of the created Opportunity
     * @throws IllegalArgumentException if the contact does not exist or the amount is invalid
     */
    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Gift amount must be a positive value.');
        }
        if (contactId == null) {
            throw new IllegalArgumentException('A contact Id is required.');
        }
        if (giftDate == null) {
            giftDate = Date.today();
        }

        List<Contact> donors = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            WITH USER_MODE
            LIMIT 1
        ];
        if (donors.isEmpty()) {
            throw new IllegalArgumentException('Contact ' + contactId + ' does not exist.');
        }
        Contact donor = donors[0];

        Savepoint sp = Database.setSavepoint();
        try {
            Opportunity gift = new Opportunity(
                Name = buildGiftName(donor, giftDate),
                AccountId = donor.AccountId,
                npsp__Primary_Contact__c = donor.Id,
                Amount = amount,
                CloseDate = giftDate,
                StageName = getClosedWonStageName()
            );
            Database.insert(gift, AccessLevel.USER_MODE);

            reconcileContactRoles(gift.Id, donor);
            reconcilePayments(gift.Id, amount, giftDate);

            return gift.Id;
        } catch (Exception e) {
            Database.rollback(sp);
            throw e;
        }
    }

    // ------------------------------------------------------------------
    // Contact roles
    // ------------------------------------------------------------------

    private static void reconcileContactRoles(Id opportunityId, Contact donor) {
        // Desired role per contact: donor -> Donor (primary), other household members -> Household Member
        Map<Id, String> desiredRoleByContact = new Map<Id, String>();
        desiredRoleByContact.put(donor.Id, DONOR_ROLE);

        if (donor.AccountId != null) {
            for (Contact member : [
                SELECT Id
                FROM Contact
                WHERE AccountId = :donor.AccountId AND Id != :donor.Id
                WITH USER_MODE
            ]) {
                desiredRoleByContact.put(member.Id, HOUSEHOLD_MEMBER_ROLE);
            }
        }

        List<OpportunityContactRole> existingRoles = [
            SELECT Id, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId = :opportunityId
            WITH USER_MODE
        ];

        List<OpportunityContactRole> toInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> toUpdate = new List<OpportunityContactRole>();
        List<OpportunityContactRole> toDelete = new List<OpportunityContactRole>();
        Set<Id> contactsWithRole = new Set<Id>();

        for (OpportunityContactRole ocr : existingRoles) {
            if (contactsWithRole.contains(ocr.ContactId)) {
                // Second role for the same contact on this gift -> duplicate, remove it
                toDelete.add(ocr);
                continue;
            }
            contactsWithRole.add(ocr.ContactId);

            if (!desiredRoleByContact.containsKey(ocr.ContactId)) {
                // Not part of the household; leave untouched (it is still that contact's only role)
                continue;
            }
            String desiredRole = desiredRoleByContact.get(ocr.ContactId);
            Boolean shouldBePrimary = (ocr.ContactId == donor.Id);
            if (ocr.Role != desiredRole || ocr.IsPrimary != shouldBePrimary) {
                ocr.Role = desiredRole;
                ocr.IsPrimary = shouldBePrimary;
                toUpdate.add(ocr);
            }
        }

        for (Id cId : desiredRoleByContact.keySet()) {
            if (!contactsWithRole.contains(cId)) {
                toInsert.add(new OpportunityContactRole(
                    OpportunityId = opportunityId,
                    ContactId = cId,
                    Role = desiredRoleByContact.get(cId),
                    IsPrimary = (cId == donor.Id)
                ));
            }
        }

        if (!toDelete.isEmpty()) {
            Database.delete(toDelete, AccessLevel.USER_MODE);
        }
        if (!toUpdate.isEmpty()) {
            Database.update(toUpdate, AccessLevel.USER_MODE);
        }
        if (!toInsert.isEmpty()) {
            Database.insert(toInsert, AccessLevel.USER_MODE);
        }
    }

    // ------------------------------------------------------------------
    // Payments
    // ------------------------------------------------------------------

    private static void reconcilePayments(Id opportunityId, Decimal amount, Date giftDate) {
        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id, npe01__Payment_Amount__c, npe01__Payment_Date__c,
                   npe01__Scheduled_Date__c, npe01__Paid__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
            WITH USER_MODE
            ORDER BY CreatedDate ASC, Id ASC
        ];

        if (existingPayments.isEmpty()) {
            // NPSP did not auto-create a payment (e.g. automatic creation disabled) -> create it
            Database.insert(new npe01__OppPayment__c(
                npe01__Opportunity__c = opportunityId,
                npe01__Payment_Amount__c = amount,
                npe01__Payment_Date__c = giftDate,
                npe01__Scheduled_Date__c = giftDate,
                npe01__Paid__c = true
            ), AccessLevel.USER_MODE);
            return;
        }

        // Keep the first payment as the single payment for the gift; remove any extras
        npe01__OppPayment__c payment = existingPayments[0];
        if (payment.npe01__Payment_Amount__c != amount
                || payment.npe01__Payment_Date__c != giftDate
                || payment.npe01__Paid__c != true) {
            payment.npe01__Payment_Amount__c = amount;
            payment.npe01__Payment_Date__c = giftDate;
            payment.npe01__Paid__c = true;
            if (payment.npe01__Scheduled_Date__c == null) {
                payment.npe01__Scheduled_Date__c = giftDate;
            }
            Database.update(payment, AccessLevel.USER_MODE);
        }

        if (existingPayments.size() > 1) {
            List<npe01__OppPayment__c> extras = new List<npe01__OppPayment__c>();
            for (Integer i = 1; i < existingPayments.size(); i++) {
                extras.add(existingPayments[i]);
            }
            Database.delete(extras, AccessLevel.USER_MODE);
        }
    }

    // ------------------------------------------------------------------
    // Helpers
    // ------------------------------------------------------------------

    private static String buildGiftName(Contact donor, Date giftDate) {
        String contactName = '';
        if (String.isNotBlank(donor.FirstName)) {
            contactName += donor.FirstName + ' ';
        }
        contactName += donor.LastName;
        String name = contactName.trim() + ' Donation ' + formatDate(giftDate);
        return name.length() > 120 ? name.substring(0, 120) : name;
    }

    private static String formatDate(Date d) {
        return String.valueOf(d.year()) + '-' + padTwo(d.month()) + '-' + padTwo(d.day());
    }

    private static String padTwo(Integer value) {
        return value < 10 ? '0' + String.valueOf(value) : String.valueOf(value);
    }

    private static String getClosedWonStageName() {
        List<OpportunityStage> stages = [
            SELECT MasterLabel
            FROM OpportunityStage
            WHERE IsActive = true AND IsClosed = true AND IsWon = true
            ORDER BY SortOrder ASC
        ];
        if (stages.isEmpty()) {
            return DEFAULT_CLOSED_WON_STAGE;
        }
        for (OpportunityStage stage : stages) {
            if (stage.MasterLabel == DEFAULT_CLOSED_WON_STAGE) {
                return stage.MasterLabel;
            }
        }
        return stages[0].MasterLabel;
    }
}
