/**
 * Creates NPSP parent/child relationships from an external family-link import.
 *
 * Only the forward record (Contact = child, Related Contact = parent, Type = Parent) is inserted.
 * NPSP's relationship trigger handler (REL_Relationships_TDTM) creates the reciprocal record on the
 * parent and resolves its type (Son / Daughter / Child) from the active Relationship Lookup setting
 * using the child's gender, so each pair ends up with exactly one record in each direction.
 */
public with sharing class FamilyService {

    @TestVisible private static final String TYPE_PARENT   = 'Parent';
    @TestVisible private static final String STATUS_CURRENT = 'Current';

    /**
     * @param parentIdByChildId key = child Contact Id, value = parent Contact Id
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // Collect valid pairs (both ids present, not the same contact)
        Map<Id, Id> validPairs = new Map<Id, Id>();
        Set<Id> childIds  = new Set<Id>();
        Set<Id> parentIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }
            validPairs.put(childId, parentId);
            childIds.add(childId);
            parentIds.add(parentId);
        }
        if (validPairs.isEmpty()) {
            return;
        }

        // Single query: any existing relationship between the two contacts, in either direction
        Set<String> existingPairKeys = new Set<String>();
        for (npe4__Relationship__c rel : [
                SELECT npe4__Contact__c, npe4__RelatedContact__c
                FROM   npe4__Relationship__c
                WHERE  (npe4__Contact__c IN :childIds  AND npe4__RelatedContact__c IN :parentIds)
                   OR  (npe4__Contact__c IN :parentIds AND npe4__RelatedContact__c IN :childIds)
                WITH USER_MODE
        ]) {
            existingPairKeys.add(pairKey(rel.npe4__Contact__c, rel.npe4__RelatedContact__c));
        }

        // Build only the forward records; NPSP creates the reciprocal automatically
        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();
        for (Id childId : validPairs.keySet()) {
            Id parentId = validPairs.get(childId);
            String forwardKey = pairKey(childId, parentId);
            String reverseKey = pairKey(parentId, childId);

            if (existingPairKeys.contains(forwardKey) || existingPairKeys.contains(reverseKey)) {
                continue; // already linked (either direction) - safe re-run
            }
            // Guard against the same pair appearing twice in this call (e.g. A->B and B->A)
            existingPairKeys.add(forwardKey);
            existingPairKeys.add(reverseKey);

            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c        = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c           = TYPE_PARENT,
                npe4__Status__c         = STATUS_CURRENT
            ));
        }

        if (!toInsert.isEmpty()) {
            // Single DML; NPSP's after-insert handler adds the reciprocal (Son/Daughter/Child) records
            Database.insert(toInsert, AccessLevel.USER_MODE);
        }
    }

    private static String pairKey(Id contactId, Id relatedContactId) {
        return String.valueOf(contactId) + '|' + String.valueOf(relatedContactId);
    }
}
