/**
 * @description NPSP TDTM trigger handler for Opportunity. Creates a single "Major gift thank-you call"
 *              Task when an Opportunity becomes Closed Won with an Amount of at least 5,000.
 *
 *              Registered via an NPSP Trigger Handler record:
 *                Class          : OPP_MajorGiftFollowUp_TDTM
 *                Object         : Opportunity
 *                Trigger Action : AfterInsert;AfterUpdate
 *                Load Order     : 5
 *                Asynchronous   : false
 *
 *              The class is only executed by NPSP's TDTM dispatcher, so deactivating the Trigger Handler
 *              record switches the behaviour off. All DML is handed back to the dispatcher through the
 *              DmlWrapper, so this handler performs 0 SOQL queries and 0 DML statements of its own.
 */
global with sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    @TestVisible private static final Decimal MAJOR_GIFT_THRESHOLD = 5000;
    @TestVisible private static final Integer FOLLOW_UP_DAYS = 3;
    @TestVisible private static final String TASK_SUBJECT = 'Major gift thank-you call';
    @TestVisible private static final String TASK_PRIORITY = 'High';
    @TestVisible private static final String TASK_STATUS = 'Not Started';

    /**
     * @description TDTM entry point, invoked by npsp.TDTM_TriggerHandler.
     * @param newlist      Trigger.new records
     * @param oldlist      Trigger.old records (null on insert)
     * @param triggerAction the trigger event being processed
     * @param objResult    describe result for the object (Opportunity)
     * @return DmlWrapper containing the Tasks to insert; NPSP executes the DML once for all handlers
     */
    global override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper dmlWrapper = new npsp.TDTM_Runnable.DmlWrapper();

        if (newlist == null || newlist.isEmpty()) {
            return dmlWrapper;
        }

        Boolean isInsert = triggerAction == npsp.TDTM_Runnable.Action.AfterInsert;
        Boolean isUpdate = triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate;

        if (!isInsert && !isUpdate) {
            return dmlWrapper;
        }

        // Index old records by Id so the handler is independent of list ordering.
        Map<Id, Opportunity> oldOppsById = new Map<Id, Opportunity>();
        if (isUpdate && oldlist != null) {
            for (SObject oldRecord : oldlist) {
                Opportunity oldOpp = (Opportunity) oldRecord;
                oldOppsById.put(oldOpp.Id, oldOpp);
            }
        }

        List<Task> tasksToInsert = new List<Task>();

        for (SObject newRecord : newlist) {
            Opportunity newOpp = (Opportunity) newRecord;

            if (!isMajorGift(newOpp)) {
                continue;
            }

            if (isUpdate) {
                Opportunity oldOpp = oldOppsById.get(newOpp.Id);
                // Already qualified before this edit -> no additional task.
                if (oldOpp != null && isMajorGift(oldOpp)) {
                    continue;
                }
            }

            tasksToInsert.add(buildFollowUpTask(newOpp));
        }

        if (!tasksToInsert.isEmpty()) {
            dmlWrapper.objectsToInsert.addAll((List<SObject>) tasksToInsert);
        }

        return dmlWrapper;
    }

    /**
     * @description An opportunity qualifies when it is Closed Won and its Amount is at least the threshold.
     *              IsWon is used rather than a hard-coded stage label so renamed/custom Closed Won stages work.
     */
    @TestVisible
    private static Boolean isMajorGift(Opportunity opp) {
        return opp != null
            && opp.IsWon == true
            && opp.Amount != null
            && opp.Amount >= MAJOR_GIFT_THRESHOLD;
    }

    /**
     * @description Builds the follow-up Task for a qualifying opportunity.
     */
    @TestVisible
    private static Task buildFollowUpTask(Opportunity opp) {
        return new Task(
            Subject = TASK_SUBJECT,
            Priority = TASK_PRIORITY,
            Status = TASK_STATUS,
            WhatId = opp.Id,
            WhoId = opp.npsp__Primary_Contact__c,
            OwnerId = opp.OwnerId,
            ActivityDate = opp.CloseDate != null ? opp.CloseDate.addDays(FOLLOW_UP_DAYS) : null
        );
    }
}
