/**
 * Resolves which records the running user is allowed to edit, using the
 * platform's own access evaluation (UserRecordAccess.HasEditAccess), which
 * already accounts for object/field permissions, ownership, sharing rules,
 * manual/apex sharing, the role hierarchy, View All / Modify All, etc.
 *
 * Platform constraints honoured here:
 *  - UserRecordAccess must be filtered by UserId and RecordId (IN list).
 *  - At most 200 record IDs may be supplied per query, so input is chunked.
 *    2,000 IDs => 10 queries, well under the 20-query budget for this method.
 *  - IDs of different objects may be mixed in a single query.
 */
public with sharing class RecordAccessService {

    /** Maximum number of record IDs UserRecordAccess accepts per query. */
    @TestVisible
    private static final Integer MAX_IDS_PER_QUERY = 200;

    /**
     * @param recordIds IDs to check (may span multiple objects, may contain nulls).
     * @return the subset of recordIds the running user can edit; never null.
     */
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editable = new Set<Id>();
        if (recordIds == null || recordIds.isEmpty()) {
            return editable;
        }

        Id runningUserId = UserInfo.getUserId();
        List<Id> chunk = new List<Id>();

        for (Id recordId : recordIds) {
            if (recordId == null) {
                continue;
            }
            chunk.add(recordId);
            if (chunk.size() == MAX_IDS_PER_QUERY) {
                collectEditable(runningUserId, chunk, editable);
                chunk = new List<Id>();
            }
        }
        if (!chunk.isEmpty()) {
            collectEditable(runningUserId, chunk, editable);
        }

        return editable;
    }

    /**
     * Queries UserRecordAccess for a single chunk (<= 200 IDs) and adds the
     * editable record IDs to the accumulator.
     */
    private static void collectEditable(Id userId, List<Id> chunk, Set<Id> editable) {
        for (UserRecordAccess access : [
            SELECT RecordId, HasEditAccess
            FROM UserRecordAccess
            WHERE UserId = :userId
              AND RecordId IN :chunk
        ]) {
            if (access.HasEditAccess == true) {
                editable.add(access.RecordId);
            }
        }
    }
}
