/**
 * Returns FB_Employee__c records for an employee directory.
 *
 * - Sharing is enforced by the `with sharing` keyword (OWD Private is respected).
 * - Object- and field-level security are enforced by querying in USER_MODE.
 * - Fields the running user cannot read are never queried, so they are absent
 *   from the returned records (not present with a null value) and the query
 *   never fails because of a non-readable field.
 * - If the running user has no read access to the object, an empty list is returned.
 */
public with sharing class EmployeeDirectoryService {

    private static final Set<String> OPTIONAL_FIELDS = new Set<String>{
        'Department__c',
        'Salary__c',
        'Personal_Email__c'
    };

    public static List<FB_Employee__c> getDirectory() {
        Schema.DescribeSObjectResult objDescribe = FB_Employee__c.SObjectType.getDescribe();

        // No object-level read access: nothing to return, and avoid a QueryException.
        if (!objDescribe.isAccessible()) {
            return new List<FB_Employee__c>();
        }

        // Id and Name are always readable when the object is readable.
        List<String> selectedFields = new List<String>{ 'Id', 'Name' };

        Map<String, Schema.SObjectField> fieldMap = objDescribe.fields.getMap();
        for (String fieldName : OPTIONAL_FIELDS) {
            Schema.SObjectField field = fieldMap.get(fieldName);
            if (field != null && field.getDescribe().isAccessible()) {
                selectedFields.add(fieldName);
            }
        }

        String soql =
            'SELECT ' + String.join(selectedFields, ', ') +
            ' FROM FB_Employee__c' +
            ' ORDER BY Name ASC';

        // USER_MODE enforces sharing, object-level and field-level security for this query.
        // Since only readable fields are selected, the query cannot fail on FLS.
        List<FB_Employee__c> results =
            (List<FB_Employee__c>) Database.query(soql, AccessLevel.USER_MODE);

        return results;
    }
}
