/**
 * Imports Contacts from the legacy system.
 *
 * Legacy contacts are existing customers, so the TAF action that creates the
 * "Send welcome pack" Task (TA_Contact_CreateWelcomeTask) is bypassed for the
 * import DML only. All other Contact automation (e.g. TA_Contact_FormatPhone)
 * still runs because we bypass the single action, not the Contact object.
 *
 * The bypass is always cleared in a finally block so it never leaks into the
 * rest of the transaction, even if the insert throws.
 */
public with sharing class ContactImportService {

    public static void importContacts(List<Contact> contacts) {
        if (contacts == null || contacts.isEmpty()) {
            return;
        }

        // Action-level bypass (MetadataTriggerHandler), NOT object-level (TriggerBase.bypass),
        // so every other registered Contact action continues to execute.
        MetadataTriggerHandler.bypass(TA_Contact_CreateWelcomeTask.class);
        try {
            insert contacts; // single DML statement, bulk-safe
        } finally {
            // Guarantee later inserts in this transaction get their welcome task again.
            MetadataTriggerHandler.clearBypass(TA_Contact_CreateWelcomeTask.class);
        }
    }
}
