File: force-app/main/default/classes/AccountOwnershipService.cls
```apex
/**
 * Reassigns ownership of Accounts and all of their Contacts to a new owner.
 *
 * - The Account update runs with the Trigger Actions Framework bypass enabled for the whole
 *   Account sObject, so no Account trigger actions (territory recalculation etc.) execute.
 * - The bypass is scoped strictly to the Account DML and is always restored afterwards
 *   (also when the DML throws), so Account automation behaves normally for the rest of the
 *   transaction, including for any Account DML performed by the Contact trigger actions.
 * - The Contact update is performed with no bypass, so all Contact trigger actions run normally.
 * - All DML is all-or-none; any exception propagates to the caller unchanged.
 * - Governor usage is independent of volume: 1 SOQL query and 2 DML statements.
 */
public inherited sharing class AccountOwnershipService {

    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }
        if (newOwnerId == null) {
            throw new IllegalArgumentException('newOwnerId is required');
        }

        // Build the Account updates without querying: only Id and OwnerId are needed.
        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                accountsToUpdate.add(new Account(Id = accountId, OwnerId = newOwnerId));
            }
        }

        // One query for every Contact belonging to the given Accounts.
        List<Contact> contactsToUpdate = [
            SELECT Id
            FROM Contact
            WHERE AccountId IN :accountIds
        ];
        for (Contact con : contactsToUpdate) {
            con.OwnerId = newOwnerId;
        }

        // Update Accounts with the whole Account sObject bypassed in TAF.
        // Respect a bypass that a caller may already have set; otherwise set it and clear it again.
        Boolean wasAlreadyBypassed = TriggerBase.isBypassed(Account.SObjectType);
        if (!wasAlreadyBypassed) {
            TriggerBase.bypass(Account.SObjectType);
        }
        try {
            if (!accountsToUpdate.isEmpty()) {
                update accountsToUpdate; // all-or-none; exceptions propagate unchanged
            }
        } finally {
            if (!wasAlreadyBypassed) {
                TriggerBase.clearBypass(Account.SObjectType);
            }
        }

        // Update Contacts with no bypass so every Contact trigger action runs normally.
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate; // all-or-none; exceptions propagate unchanged
        }
    }
}
