/**
 * DML-less unit tests for TA_Opportunity_GuardAmountDecrease.
 *
 * Following the Trigger Actions Framework recommendation, the action's context method is
 * invoked directly with in-memory records carrying fake Ids. No DML and no SOQL are performed,
 * and errors are asserted through the SObject error API (hasErrors / getErrors).
 */
@IsTest
private class TA_Opportunity_GuardAmountDecreaseTest {
    private static final Schema.SObjectType OPP_TYPE = Opportunity.SObjectType;

    /**
     * Builds an old/new record pair sharing the same fake Id.
     * Index 0 is the "old" record, index 1 is the "new" record.
     */
    private static Opportunity[] buildPair(Decimal previousAmount, Decimal newAmount) {
        Id fakeId = TriggerTestUtility.getFakeId(OPP_TYPE);
        Opportunity oldOpp = new Opportunity(Id = fakeId, Amount = previousAmount);
        Opportunity newOpp = new Opportunity(Id = fakeId, Amount = newAmount);
        return new Opportunity[] { oldOpp, newOpp };
    }

    private static void runAction(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(triggerNew, triggerOld);
    }

    private static void assertSingleGuardError(Opportunity opp) {
        Assert.isTrue(opp.hasErrors(), 'Expected the record to carry an error: ' + opp);
        List<Database.Error> errors = opp.getErrors();
        Assert.areEqual(1, errors.size(), 'Expected exactly one error on the record: ' + opp);
        Assert.areEqual(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            errors[0].getMessage(),
            'Unexpected error message on the record: ' + opp
        );
    }

    private static void assertNoError(Opportunity opp) {
        Assert.isFalse(opp.hasErrors(), 'Expected no error on the record: ' + opp);
        Assert.areEqual(0, opp.getErrors().size(), 'Expected zero errors on the record: ' + opp);
    }

    @IsTest
    private static void reductionOfMoreThanHalfIsRejected() {
        Opportunity[] pair = buildPair(1000, 499);
        List<Opportunity> triggerOld = new List<Opportunity>{ pair[0] };
        List<Opportunity> triggerNew = new List<Opportunity>{ pair[1] };

        Test.startTest();
        runAction(triggerNew, triggerOld);
        Test.stopTest();

        assertSingleGuardError(triggerNew[0]);
        assertNoError(triggerOld[0]);
    }

    @IsTest
    private static void reductionOfExactlyHalfIsAccepted() {
        Opportunity[] pair = buildPair(1000, 500);
        List<Opportunity> triggerOld = new List<Opportunity>{ pair[0] };
        List<Opportunity> triggerNew = new List<Opportunity>{ pair[1] };

        Test.startTest();
        runAction(triggerNew, triggerOld);
        Test.stopTest();

        assertNoError(triggerNew[0]);
    }

    @IsTest
    private static void increaseIsAccepted() {
        Opportunity[] pair = buildPair(1000, 1500);
        List<Opportunity> triggerOld = new List<Opportunity>{ pair[0] };
        List<Opportunity> triggerNew = new List<Opportunity>{ pair[1] };

        Test.startTest();
        runAction(triggerNew, triggerOld);
        Test.stopTest();

        assertNoError(triggerNew[0]);
    }

    @IsTest
    private static void nullPreviousAmountIsAcceptedWithoutException() {
        Opportunity[] pair = buildPair(null, 10);
        List<Opportunity> triggerOld = new List<Opportunity>{ pair[0] };
        List<Opportunity> triggerNew = new List<Opportunity>{ pair[1] };

        Exception caught;
        Test.startTest();
        try {
            runAction(triggerNew, triggerOld);
        } catch (Exception e) {
            caught = e;
        }
        Test.stopTest();

        Assert.isNull(caught, 'No exception expected when the previous Amount is null');
        assertNoError(triggerNew[0]);
    }

    @IsTest
    private static void nullNewAmountIsAcceptedWithoutException() {
        Opportunity[] pair = buildPair(1000, null);
        List<Opportunity> triggerOld = new List<Opportunity>{ pair[0] };
        List<Opportunity> triggerNew = new List<Opportunity>{ pair[1] };

        Exception caught;
        Test.startTest();
        try {
