        assertSingleGuardError(tinyTooLow[1]);

        assertNoError(exactHalf[1]);
        assertNoError(increased[1]);
        assertNoError(nullPrevious[1]);
        assertNoError(unchanged[1]);

        Integer recordsWithErrors = 0;
        for (Opportunity opp : triggerNew) {
            if (opp.hasErrors()) {
                recordsWithErrors++;
            }
        }
