/**
 * Trigger action (Trigger Actions Framework) that prevents two Contacts of the same Account
 * from sharing an email address (case-insensitive).
 *
 * Runs without sharing on purpose: a uniqueness rule must consider every Contact of the
 * Account, regardless of the running user's record visibility.
 */
public without sharing class TA_Contact_PreventDuplicateEmail implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {
    @TestVisible
    private static final String DUPLICATE_EMAIL_ERROR = 'Another contact on this account already uses this email address.';
    private static final String KEY_SEPARATOR = '|';

    public void beforeInsert(List<SObject> triggerNew) {
        validate((List<Contact>) triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        validate((List<Contact>) triggerNew, new Map<Id, Contact>((List<Contact>) triggerOld));
    }

    private void validate(List<Contact> newContacts, Map<Id, Contact> oldMap) {
        List<Contact> candidates = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();
        // Account/email combinations that are already taken by another contact.
        Set<String> usedKeys = new Set<String>();

        for (Contact c : newContacts) {
            if (!hasAccountAndEmail(c)) {
                continue;
            }
            if (requiresCheck(c, oldMap)) {
                candidates.add(c);
                accountIds.add(c.AccountId);
                emails.add(normalizeEmail(c.Email));
            } else {
                // Email and Account unchanged in this save: the contact keeps occupying its
                // combination, so a changed contact in the same save may not take it.
                usedKeys.add(buildKey(c));
            }
        }

        if (candidates.isEmpty()) {
            return;
        }

        // Records in this transaction are evaluated with their NEW values above, so their
        // stored (old) values must not count as conflicts; a contact never conflicts with itself.
        Set<Id> idsInTransaction = oldMap == null ? new Set<Id>() : oldMap.keySet();

        // Single query. SOQL text comparison is case-insensitive, so lower-cased emails match.
        for (Contact existing : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds AND Email IN :emails
        ]) {
            if (idsInTransaction.contains(existing.Id)) {
                continue;
            }
            usedKeys.add(buildKey(existing));
        }

        // First occurrence in the list wins; later ones in the same save are rejected.
        for (Contact c : candidates) {
            String key = buildKey(c);
            if (usedKeys.contains(key)) {
                c.addError(DUPLICATE_EMAIL_ERROR);
            } else {
                usedKeys.add(key);
            }
        }
    }

    private static Boolean hasAccountAndEmail(Contact c) {
        return c.AccountId != null && String.isNotBlank(c.Email);
    }

    private static Boolean requiresCheck(Contact c, Map<Id, Contact> oldMap) {
        if (oldMap == null) {
            return true; // insert
        }
        Contact oldContact = oldMap.get(c.Id);
        if (oldContact == null) {
            return true;
        }
        return c.AccountId != oldContact.AccountId ||
            normalizeEmail(c.Email) != normalizeEmail(oldContact.Email);
    }

    private static String normalizeEmail(String email) {
        return email == null ? null : email.trim().toLowerCase();
    }

    private static String buildKey(Contact c) {
        return String.valueOf(c.AccountId) + KEY_SEPARATOR + normalizeEmail(c.Email);
    }
}
