/**
 * Trigger Actions Framework action (after update, Opportunity).
 *
 * Creates one completed "Amount changed" Task on every Opportunity whose Amount changed
 * in this update. Registered via Trigger_Action__mdt.TA_Opportunity_LogAmountChange
 * (Order__c = 10, before TA_Opportunity_RoundAmount at Order__c = 20).
 *
 * TA_Opportunity_RoundAmount updates the same opportunities again in the same transaction,
 * which re-runs this action with a changed Amount (e.g. 100.4 -> 100). That rounding is a
 * consequence of the user's change, not a new one, so a transaction-scoped set of already
 * logged opportunity Ids guarantees at most one audit task per opportunity per transaction.
 */
public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    @TestVisible
    private static final String TASK_SUBJECT = 'Amount changed';
    @TestVisible
    private static final String TASK_STATUS = 'Completed';

    // Opportunity Ids that already received an audit task in this transaction.
    @TestVisible
    private static Set<Id> loggedOpportunityIds = new Set<Id>();

    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        Map<Id, Opportunity> oldById = new Map<Id, Opportunity>(triggerOld);
        List<Task> tasksToInsert = new List<Task>();

        for (Opportunity opp : triggerNew) {
            if (loggedOpportunityIds.contains(opp.Id)) {
                // Already audited in this transaction (e.g. re-entry caused by the rounding action).
                continue;
            }
            Opportunity oldOpp = oldById.get(opp.Id);
            if (oldOpp == null || !amountChanged(oldOpp, opp)) {
                continue;
            }
            tasksToInsert.add(
                new Task(
                    Subject = TASK_SUBJECT,
                    Status = TASK_STATUS,
                    WhatId = opp.Id
                )
            );
            loggedOpportunityIds.add(opp.Id);
        }

        if (!tasksToInsert.isEmpty()) {
            // Single DML statement per trigger execution; audit records must not be silently skipped.
            insert tasksToInsert;
        }
    }

    private static Boolean amountChanged(Opportunity oldOpp, Opportunity newOpp) {
        if (oldOpp.Amount == null && newOpp.Amount == null) {
            return false;
        }
        if (oldOpp.Amount == null || newOpp.Amount == null) {
            return true;
        }
        return oldOpp.Amount != newOpp.Amount;
    }
}
