/**
 * Singleton that holds the data shared by the Contact trigger actions so that the
 * parent Accounts are queried exactly once per trigger execution.
 *
 * Follows the Trigger Actions Framework "avoid repeated queries" pattern: the inner
 * `Service` class is itself a trigger action, registered first in the before insert
 * context, that (re)loads the shared map on every trigger execution.
 *
 * Runs in the sharing mode of the trigger (system mode) so that defaults can be
 * derived from the parent Account regardless of the running user's sharing.
 */
public inherited sharing class TA_Contact_Queries {
    private static TA_Contact_Queries instance;

    /**
     * Parent Accounts of the contacts in the current trigger execution, keyed by Account Id.
     * Reloaded by `TA_Contact_Queries.Service` at the start of every before insert execution.
     */
    public Map<Id, Account> accountsById = new Map<Id, Account>();

    private TA_Contact_Queries() {
    }

    public static TA_Contact_Queries getInstance() {
        if (instance == null) {
            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    /**
     * Trigger action that loads the shared Account map. Registered as
     * `TA_Contact_Queries.Service` with Order 1 in before insert so it executes before
     * every action that depends on the map.
     */
    public class Service implements TriggerAction.BeforeInsert {
        public void beforeInsert(List<Contact> triggerNew) {
            // Always reload: later DML in the same transaction may involve other accounts.
            TA_Contact_Queries.getInstance().accountsById = queryAccounts(triggerNew);
        }

        private Map<Id, Account> queryAccounts(List<Contact> contacts) {
            Set<Id> accountIds = new Set<Id>();
            for (Contact contact : contacts) {
                if (contact.AccountId != null) {
                    accountIds.add(contact.AccountId);
                }
            }
            if (accountIds.isEmpty()) {
                return new Map<Id, Account>();
            }
            return new Map<Id, Account>(
                [
                    SELECT
                        Id,
                        BillingStreet,
                        BillingCity,
                        BillingPostalCode,
                        BillingCountry,
                        AccountSource
                    FROM Account
                    WHERE Id IN :accountIds
                ]
            );
        }
    }
}
