/**
 * Before insert trigger action on Contact.
 *
 * When a new contact is linked to an Account and has no mailing address at all
 * (MailingStreet, MailingCity, MailingPostalCode and MailingCountry all blank), the
 * account's billing address is copied into the mailing address fields. A contact that
 * has any of those four fields populated keeps its own address. Contacts without an
 * Account are left untouched.
 *
 * Parent accounts are read from the shared `TA_Contact_Queries` singleton, which is
 * loaded once per trigger execution by `TA_Contact_Queries.Service`.
 */
public inherited sharing class TA_Contact_InheritMailingAddress implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<Contact> triggerNew) {
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;

        for (Contact contact : triggerNew) {
            if (contact.AccountId == null || !hasBlankMailingAddress(contact)) {
                continue;
            }
            Account parent = accountsById.get(contact.AccountId);
            if (parent == null) {
                continue;
            }
            contact.MailingStreet = parent.BillingStreet;
            contact.MailingCity = parent.BillingCity;
            contact.MailingPostalCode = parent.BillingPostalCode;
            contact.MailingCountry = parent.BillingCountry;
        }
    }

    private Boolean hasBlankMailingAddress(Contact contact) {
        return String.isBlank(contact.MailingStreet) &&
            String.isBlank(contact.MailingCity) &&
            String.isBlank(contact.MailingPostalCode) &&
            String.isBlank(contact.MailingCountry);
    }
}
